__mods["Core/Assets"] = function()
-- จัดการรูปพื้นหลัง: ใช้ไฟล์ของผู้ใช้ (BALLKUN_V6/bg.jpg / bg.png) ก่อน ไม่งั้นใช้ภาพเริ่มต้นที่ฝังไว้
local A = {}
local DIR, DEF = "BALLKUN_V6", "BALLKUN_V6/bg_default.jpg"

local function fns()
	return type(isfile) == "function" and type(writefile) == "function" and (type(getcustomasset) == "function" or type(getsynasset) == "function")
end

function A.canUse() return fns() end

-- คืน url ของรูปที่ใช้ได้ หรือ nil ถ้าตัวรันไม่รองรับ
function A.bgUrl()
	if not fns() then return nil end
	local get = getcustomasset or getsynasset
	local ok, url = pcall(function()
		if type(isfolder) == "function" and type(makefolder) == "function" and not isfolder(DIR) then makefolder(DIR) end
		for _, p in ipairs({ DIR .. "/bg.jpg", DIR .. "/bg.png" }) do
			if isfile(p) then return get(p) end
		end
		if not isfile(DEF) then writefile(DEF, require("Assets/BgData")) end
		return get(DEF)
	end)
	return ok and url or nil
end

return A

end
__mods["Core/Bus"] = function()
-- Event Bus: ระบบสื่อสารแบบ event-driven ระหว่างโมดูล
local Bus = { _h = {} }

function Bus.on(name, fn)
	local list = Bus._h[name]
	if not list then
		list = {}
		Bus._h[name] = list
	end
	table.insert(list, fn)
	return function()
		local i = table.find(list, fn)
		if i then table.remove(list, i) end
	end
end

function Bus.fire(name, ...)
	local list = Bus._h[name]
	if not list then return end
	for _, fn in ipairs(table.clone(list)) do
		local ok, err = pcall(fn, ...)
		if not ok then warn("[BALLKUN][Bus:" .. name .. "] " .. tostring(err)) end
	end
end

function Bus.reset()
	Bus._h = {}
end

return Bus

end
__mods["Core/Config"] = function()
-- ตั้งค่าผู้ใช้ เก็บเป็นไฟล์ในเครื่อง (ถ้าตัวรันรองรับ writefile) ไม่มี secret ใด ๆ
local HttpService = game:GetService("HttpService")
local Bus = require("Core/Bus")

local DIR, PATH = "BALLKUN_V6", "BALLKUN_V6/config.json"
local Config = {
	data = {},
	defaults = {
		uiScale = 1,
		glass = 0.12,
		minToastPriority = 1,
		windowW = 640,
		windowH = 380,
		pistonAutoStart = false,
		pistonDiscordOpen = true,
		pistonDiscordClose = true,
		pistonDiscordChange = true,
		pistonSigSpot = false,
		accentColor = "39FF8C", panelColor = "08110D", textColor = "FFFFFF", dimColor = "A0BEAF",
		fontId = "Gotham", fontScale = 1,
		bgEnabled = true, bgVisible = 0.55, bgAsset = "",
		privateLink = "",
		toastTime = 1, toastMax = 4,
	},
}

local pending = false

local function canFile()
	return type(isfile) == "function" and type(readfile) == "function" and type(writefile) == "function"
end

function Config.load()
	Config.data = table.clone(Config.defaults)
	if canFile() then
		local ok, raw = pcall(function() return isfile(PATH) and readfile(PATH) or nil end)
		if ok and raw then
			local ok2, t = pcall(HttpService.JSONDecode, HttpService, raw)
			if ok2 and type(t) == "table" then
				for k, v in pairs(Config.defaults) do
					if type(t[k]) == type(v) then Config.data[k] = t[k] end
				end
			end
		end
	end
end

function Config.save()
	if not canFile() then return false end
	return pcall(function()
		if type(isfolder) == "function" and type(makefolder) == "function" and not isfolder(DIR) then makefolder(DIR) end
		writefile(PATH, HttpService:JSONEncode(Config.data))
	end)
end

function Config.get(k)
	return Config.data[k]
end

function Config.set(k, v)
	Config.data[k] = v
	Bus.fire("Config:" .. k, v)
	if not pending then
		pending = true
		task.delay(0.6, function()
			pending = false
			Config.save()
		end)
	end
end

Config.canPersist = canFile

return Config

end
__mods["Core/Discord"] = function()
-- ส่งข้อความเข้า Discord Webhook: คิว + คูลดาวน์ + retry (เก็บลิงก์ในไฟล์ในเครื่องเท่านั้น ไม่ลง log/แจ้งเตือน)
local HttpService = game:GetService("HttpService")
local Players = game:GetService("Players")
local Notify = require("Core/Notify")
local Log = require("Core/Log")
local Bus = require("Core/Bus")
local Config = require("Core/Config")

local DIR, FILE = "BALLKUN_V6", "BALLKUN_V6/webhook.txt"
local D = { url = nil }
local queue, running = {}, false

local function httpFn()
	return (syn and syn.request) or request or http_request or (http and http.request)
end

local function canFile()
	return type(isfile) == "function" and type(readfile) == "function" and type(writefile) == "function"
end

function D.isValid(u)
	if type(u) ~= "string" then return false end
	return u:match("^https://discord%.com/api/webhooks/%d+/[%w_%-]+$") ~= nil
		or u:match("^https://discordapp%.com/api/webhooks/%d+/[%w_%-]+$") ~= nil
		or u:match("^https://canary%.discord%.com/api/webhooks/%d+/[%w_%-]+$") ~= nil
		or u:match("^https://ptb%.discord%.com/api/webhooks/%d+/[%w_%-]+$") ~= nil
end

function D.mask()
	if not D.url then return "ยังไม่ได้ตั้ง" end
	local head = D.url:match("^(https://[^/]+/api/webhooks/%d+/)")
	return (head or "") .. "••••••••"
end

function D.hasUrl() return D.url ~= nil end
function D.canPersist() return canFile() end
function D.canSend() return httpFn() ~= nil end

function D.load()
	if not canFile() then return end
	local ok, raw = pcall(function() return isfile(FILE) and readfile(FILE) or nil end)
	if ok and raw then
		raw = raw:gsub("%s+", "")
		if D.isValid(raw) then D.url = raw end
	end
end

function D.save(u)
	u = tostring(u or ""):gsub("%s+", "")
	if not D.isValid(u) then return false, "รูปแบบลิงก์ไม่ถูกต้อง (ต้องเป็น https://discord.com/api/webhooks/ตัวเลข/โทเคน)" end
	D.url = u
	if canFile() then
		pcall(function()
			if type(isfolder) == "function" and type(makefolder) == "function" and not isfolder(DIR) then makefolder(DIR) end
			writefile(FILE, u)
		end)
	end
	Log.write("discord", "ok", "ตั้งค่า Webhook แล้ว")
	Bus.fire("DiscordChanged")
	return true
end

function D.clear()
	D.url = nil
	queue = {}
	if canFile() then pcall(function() if isfile(FILE) then delfile(FILE) end end) end
	Log.write("discord", "info", "ลบ Webhook แล้ว")
	Bus.fire("DiscordChanged")
end

local function fail(job, why)
	Log.write("discord", "warn", "ส่งไม่สำเร็จ: " .. tostring(why))
	Notify.push({ key = "dc_fail", cooldown = 60, title = "ส่ง Discord ไม่สำเร็จ", text = tostring(why), level = "warn", system = "discord" })
	if job.cb then job.cb(false, why) end
end

local function pump()
	if running then return end
	running = true
	task.spawn(function()
		while #queue > 0 do
			local job = table.remove(queue, 1)
			local req, url = httpFn(), D.url
			if not req or not url then
				fail(job, not req and "ตัวรันไม่รองรับ HTTP request" or "ยังไม่ได้ตั้ง Webhook")
			else
				local ok, res = pcall(req, {
					Url = url, Method = "POST", Headers = { ["Content-Type"] = "application/json" },
					Body = HttpService:JSONEncode(job.payload),
				})
				local code = ok and type(res) == "table" and res.StatusCode or nil
				if code and code >= 200 and code < 300 then
					if job.cb then job.cb(true) end
				else
					job.tries += 1
					local wait = 2 * job.tries
					if code == 429 then
						local ra = 1.5
						pcall(function() ra = HttpService:JSONDecode(res.Body).retry_after or 1.5 end)
						wait = ra + 0.2
					end
					if job.tries < 4 then
						table.insert(queue, 1, job)
						task.wait(wait)
					else
						fail(job, code and ("HTTP " .. code) or "เชื่อมต่อไม่ได้")
					end
				end
			end
			task.wait(1.2) -- คูลดาวน์ระหว่างข้อความ
		end
		running = false
	end)
end

-- payload = { content?, embeds? }  cb(ok, why)
function D.send(payload, cb)
	if not D.url then
		if cb then cb(false, "ยังไม่ได้ตั้ง Webhook") end
		return false
	end
	table.insert(queue, { payload = payload, tries = 0, cb = cb })
	pump()
	return true
end

function D.isPrivateServer() return game.PrivateServerId ~= "" end

-- ลิงก์เซิร์ฟส่วนตัวที่ผู้ใช้วางเอง (Roblox ไม่เปิดเผยโค้ดเชิญให้สคริปต์ จึงต้องวางลิงก์เอง)
function D.validPrivate(u)
	u = tostring(u or ""):gsub("%s+", "")
	if #u < 20 or #u > 400 or u:find("[%c<>\"]") then return false, u end
	if u:match("^https://www%.roblox%.com/") or u:match("^https://roblox%.com/") then return true, u end
	return false, u
end

function D.setPrivateLink(u)
	local ok, clean = D.validPrivate(u)
	if not ok then return false, "ลิงก์ต้องขึ้นต้นด้วย https://www.roblox.com/ (ลิงก์เชิญเซิร์ฟส่วนตัว)" end
	Config.set("privateLink", clean)
	Bus.fire("LinkChanged")
	return true
end

function D.clearPrivateLink()
	Config.set("privateLink", "")
	Bus.fire("LinkChanged")
end

-- คืน (ลิงก์, ชนิด) ชนิด = "public" | "private" ; ไม่มีลิงก์ที่ใช้ได้ = nil
function D.serverLink()
	if D.isPrivateServer() then
		local p = Config.get("privateLink")
		if type(p) == "string" and p ~= "" then return p, "private" end
		return nil, "private"
	end
	if game.JobId == "" then return nil, "public" end
	return string.format("https://www.roblox.com/games/start?placeId=%d&gameInstanceId=%s", game.PlaceId, game.JobId), "public"
end

function D.sendLink(cb)
	local link, kind = D.serverLink()
	if not link then
		if cb then cb(false, kind == "private" and "อยู่เซิร์ฟส่วนตัวแต่ยังไม่ได้วางลิงก์" or "อ่าน Job ID ไม่ได้") end
		return false
	end
	return D.send({ content = "<" .. link .. ">", embeds = { {
		title = "🔗 SERVER LINK", url = link, color = 0x39FF8C,
		fields = {
			{ name = "🏪 เกม", value = "MAHANAKHON RACING", inline = true },
			{ name = "👥 ผู้เล่น", value = #Players:GetPlayers() .. "/" .. Players.MaxPlayers, inline = true },
			{ name = "🔐 ชนิด", value = kind == "private" and "PRIVATE" or "PUBLIC", inline = true },
			{ name = "🌐 SERVER LINK", value = link },
		},
		timestamp = os.date("!%Y-%m-%dT%H:%M:%SZ"),
		footer = { text = "BALL KUN HUB V6" },
	} } }, cb)
end

function D.sendTest(cb)
	local link = D.serverLink()
	return D.send({ embeds = { {
		title = "✅ BALL KUN HUB — ทดสอบ Webhook",
		color = 0x39FF8C,
		fields = {
			{ name = "🏪 เกม", value = "MAHANAKHON RACING", inline = true },
			{ name = "👥 ผู้เล่น", value = #Players:GetPlayers() .. " / " .. Players.MaxPlayers, inline = true },
			{ name = "🌐 SERVER LINK", value = link or "UNKNOWN" },
		},
		timestamp = os.date("!%Y-%m-%dT%H:%M:%SZ"),
	} } }, cb)
end

return D

end
__mods["Core/Log"] = function()
-- บันทึกประวัติการทำงาน (ring buffer จำกัดขนาด ป้องกันกินหน่วยความจำ)
local Bus = require("Core/Bus")
local Log = { _buf = {}, MAX = 200 }

function Log.write(system, level, msg)
	table.insert(Log._buf, 1, { t = os.time(), system = system, level = level, msg = tostring(msg) })
	if #Log._buf > Log.MAX then table.remove(Log._buf) end
	Bus.fire("Log", Log._buf[1])
end

function Log.recent(n)
	local out = {}
	for i = 1, math.min(n or 20, #Log._buf) do out[i] = Log._buf[i] end
	return out
end

return Log

end
__mods["Core/Maid"] = function()
-- Maid: เก็บ connection/instance แล้วล้างทีเดียว (กัน Memory Leak)
local Maid = {}
Maid.__index = Maid

function Maid.new()
	return setmetatable({ _t = {} }, Maid)
end

function Maid:Give(x)
	table.insert(self._t, x)
	return x
end

function Maid:Clean()
	local t = self._t
	self._t = {}
	for i = #t, 1, -1 do
		local x = t[i]
		local ty = typeof(x)
		if ty == "RBXScriptConnection" then
			x:Disconnect()
		elseif ty == "Instance" then
			x:Destroy()
		elseif type(x) == "function" then
			pcall(x)
		elseif type(x) == "table" and type(x.Destroy) == "function" then
			pcall(x.Destroy, x)
		end
	end
end

return Maid

end
__mods["Core/Notify"] = function()
-- ระบบแจ้งเตือน: ระดับความสำคัญ + กันซ้ำ (key+cooldown) + ประวัติจำกัดขนาด
local Bus = require("Core/Bus")

local Notify = { history = {}, MAX = 100 }
local lastShown = {}
local DEFAULT_PRI = { info = 1, ok = 2, warn = 3, crit = 4 }

-- n = { title, text, level = info|ok|warn|crit, priority = 1..4, key, cooldown, system }
function Notify.push(n)
	n.level = n.level or "info"
	n.priority = n.priority or DEFAULT_PRI[n.level] or 1
	n.time = os.time()
	if n.key then
		local now = os.clock()
		if lastShown[n.key] and now - lastShown[n.key] < (n.cooldown or 30) then return false end
		lastShown[n.key] = now
	end
	table.insert(Notify.history, 1, n)
	if #Notify.history > Notify.MAX then table.remove(Notify.history) end
	Bus.fire("Notify", n)
	return true
end

function Notify.clear()
	Notify.history = {}
	Bus.fire("NotifyCleared")
end

return Notify

end
__mods["Core/Registry"] = function()
-- ทะเบียนระบบ: ทุกระบบเปิด/ปิดแยกกันได้ + ปุ่มหยุดฉุกเฉิน
local Bus = require("Core/Bus")
local Log = require("Core/Log")
local Notify = require("Core/Notify")

local Registry = { _list = {}, _by = {} }

-- def = { id, nameTh, nameEn, start = function(), stop = function() }
function Registry.register(def)
	assert(def.id and def.start and def.stop, "system def ไม่ครบ")
	if Registry._by[def.id] then return end
	def.enabled = false
	Registry._by[def.id] = def
	table.insert(Registry._list, def)
	Bus.fire("SystemChanged", def.id, false)
end

function Registry.list() return Registry._list end
function Registry.isEnabled(id) local d = Registry._by[id]; return d ~= nil and d.enabled end

function Registry.countEnabled()
	local n = 0
	for _, d in ipairs(Registry._list) do if d.enabled then n += 1 end end
	return n
end

function Registry.setEnabled(id, on)
	local d = Registry._by[id]
	if not d or d.enabled == on then return d ~= nil and d.enabled == on end
	local ok, err = pcall(on and d.start or d.stop)
	if not ok then
		Log.write(id, "crit", "ผิดพลาด: " .. tostring(err))
		Notify.push({ key = "err:" .. id, title = d.nameTh or id, text = "ระบบผิดพลาด: " .. tostring(err), level = "crit", system = id })
		return false
	end
	d.enabled = on
	Log.write(id, on and "ok" or "info", on and "เปิดระบบ" or "ปิดระบบ")
	Bus.fire("SystemChanged", id, on)
	return true
end

function Registry.stopAll(reason)
	local n = 0
	for _, d in ipairs(Registry._list) do
		if d.enabled then
			pcall(d.stop)
			d.enabled = false
			n += 1
			Bus.fire("SystemChanged", d.id, false)
		end
	end
	Log.write("core", "crit", "EMERGENCY STOP: " .. tostring(reason))
	Bus.fire("EmergencyStop", reason)
	Notify.push({
		title = "หยุดระบบทั้งหมดแล้ว", level = "crit",
		text = n > 0 and ("ปิดระบบที่ทำงานอยู่ " .. n .. " ระบบ") or "ไม่มีระบบที่ทำงานอยู่",
	})
	return n
end

return Registry

end
__mods["Core/Theme"] = function()
-- Black Emerald + Neon Green (ค่าเริ่มต้น) · ปรับสี/ฟอนต์/ขนาดตัวอักษรได้ด้วย Theme.apply(config.data)
local DEF = {
	accent = "39FF8C", panel = "08110D", text = "FFFFFF", dim = "A0BEAF",
}

local Theme = {
	bg = Color3.fromRGB(4, 9, 7),
	panel = Color3.fromRGB(8, 17, 13),
	card = Color3.fromRGB(13, 26, 20),
	cardHi = Color3.fromRGB(22, 44, 32),
	emerald = Color3.fromRGB(16, 185, 129),
	emeraldDark = Color3.fromRGB(10, 67, 47),
	neon = Color3.fromRGB(57, 255, 140),
	white = Color3.fromRGB(255, 255, 255),
	dim = Color3.fromRGB(160, 190, 175),
	off = Color3.fromRGB(40, 48, 44),
	info = Color3.fromRGB(96, 165, 250),
	ok = Color3.fromRGB(57, 255, 140),
	warn = Color3.fromRGB(251, 191, 36),
	crit = Color3.fromRGB(248, 90, 90),
	fontBold = Enum.Font.GothamBold,
	fontMed = Enum.Font.GothamMedium,
	fontBlack = Enum.Font.GothamBlack,
	fs = 1,
	DEFAULTS = DEF,
}

-- ฟอนต์ที่เลือกได้ (บางฟอนต์ไม่มีตัวอักษรไทย Roblox จะใช้ฟอนต์สำรองแทน)
Theme.FONTS = {
	{ id = "Gotham", name = "Gotham", med = Enum.Font.GothamMedium, bold = Enum.Font.GothamBold, black = Enum.Font.GothamBlack },
	{ id = "SourceSans", name = "Source Sans", med = Enum.Font.SourceSans, bold = Enum.Font.SourceSansBold, black = Enum.Font.SourceSansBold },
	{ id = "Ubuntu", name = "Ubuntu", med = Enum.Font.Ubuntu, bold = Enum.Font.Ubuntu, black = Enum.Font.Ubuntu },
	{ id = "Roboto", name = "Roboto", med = Enum.Font.Roboto, bold = Enum.Font.Roboto, black = Enum.Font.Roboto },
	{ id = "Nunito", name = "Nunito", med = Enum.Font.Nunito, bold = Enum.Font.Nunito, black = Enum.Font.Nunito },
	{ id = "Arial", name = "Arial", med = Enum.Font.Arial, bold = Enum.Font.ArialBold, black = Enum.Font.ArialBold },
	{ id = "Oswald", name = "Oswald", med = Enum.Font.Oswald, bold = Enum.Font.Oswald, black = Enum.Font.Oswald },
	{ id = "SciFi", name = "Sci-Fi", med = Enum.Font.SciFi, bold = Enum.Font.SciFi, black = Enum.Font.SciFi },
	{ id = "Michroma", name = "Michroma", med = Enum.Font.Michroma, bold = Enum.Font.Michroma, black = Enum.Font.Michroma },
	{ id = "Code", name = "Code", med = Enum.Font.Code, bold = Enum.Font.Code, black = Enum.Font.Code },
}

function Theme.parseHex(s, fallback)
	s = tostring(s or ""):gsub("^#", "")
	if #s == 6 and s:match("^%x+$") then
		return Color3.fromRGB(tonumber(s:sub(1, 2), 16), tonumber(s:sub(3, 4), 16), tonumber(s:sub(5, 6), 16))
	end
	return fallback
end

function Theme.toHex(c)
	return string.format("%02X%02X%02X", math.floor(c.R * 255 + 0.5), math.floor(c.G * 255 + 0.5), math.floor(c.B * 255 + 0.5))
end

function Theme.isHex(s)
	s = tostring(s or ""):gsub("^#", "")
	return #s == 6 and s:match("^%x+$") ~= nil
end

local black, white = Color3.new(0, 0, 0), Color3.new(1, 1, 1)

-- d = Config.data
function Theme.apply(d)
	d = d or {}
	local accent = Theme.parseHex(d.accentColor, Theme.parseHex(DEF.accent))
	local panel = Theme.parseHex(d.panelColor, Theme.parseHex(DEF.panel))
	Theme.neon, Theme.ok = accent, accent
	if Theme.toHex(accent) == DEF.accent then
		Theme.emerald, Theme.emeraldDark = Color3.fromRGB(16, 185, 129), Color3.fromRGB(10, 67, 47)
	else
		Theme.emerald, Theme.emeraldDark = accent:Lerp(black, 0.35), accent:Lerp(black, 0.72)
	end
	Theme.panel = panel
	Theme.bg = panel:Lerp(black, 0.4)
	Theme.card = panel:Lerp(accent, 0.07)
	Theme.cardHi = panel:Lerp(accent, 0.18)
	Theme.off = panel:Lerp(white, 0.14)
	Theme.white = Theme.parseHex(d.textColor, Theme.parseHex(DEF.text))
	Theme.dim = Theme.parseHex(d.dimColor, Theme.parseHex(DEF.dim))
	for _, f in ipairs(Theme.FONTS) do
		if f.id == d.fontId then Theme.fontMed, Theme.fontBold, Theme.fontBlack = f.med, f.bold, f.black end
	end
	Theme.fs = math.clamp(tonumber(d.fontScale) or 1, 0.8, 1.3)
end

-- ขนาดตัวอักษรที่คูณตามที่ผู้ใช้ตั้ง
function Theme.sz(n) return math.max(8, math.floor(n * Theme.fs + 0.5)) end

function Theme.levelColor(level)
	return Theme[level] or Theme.info
end

return Theme

end
__mods["Core/Util"] = function()
local TweenService = game:GetService("TweenService")
local UIS = game:GetService("UserInputService")

local Util = {}

function Util.new(class, props, children)
	local o = Instance.new(class)
	local parent
	for k, v in pairs(props or {}) do
		if k == "Parent" then parent = v else o[k] = v end
	end
	for _, c in ipairs(children or {}) do c.Parent = o end
	if parent then o.Parent = parent end
	return o
end

function Util.corner(o, r)
	return Util.new("UICorner", { CornerRadius = UDim.new(0, r), Parent = o })
end

function Util.stroke(o, color, thick, trans)
	return Util.new("UIStroke", {
		Color = color, Thickness = thick or 1, Transparency = trans or 0,
		ApplyStrokeMode = Enum.ApplyStrokeMode.Border, Parent = o,
	})
end

function Util.gradient(o, c1, c2, rot)
	return Util.new("UIGradient", { Color = ColorSequence.new(c1, c2), Rotation = rot or 90, Parent = o })
end

function Util.padding(o, l, t, r, b)
	return Util.new("UIPadding", {
		PaddingLeft = UDim.new(0, l), PaddingTop = UDim.new(0, t or l),
		PaddingRight = UDim.new(0, r or l), PaddingBottom = UDim.new(0, b or t or l), Parent = o,
	})
end

function Util.tween(o, props, dur, style, dir)
	local t = TweenService:Create(o, TweenInfo.new(dur or 0.2, style or Enum.EasingStyle.Quad, dir or Enum.EasingDirection.Out), props)
	t:Play()
	return t
end

function Util.fmtNum(n)
	local s = tostring(math.floor(math.abs(n)))
	local r = s:reverse():gsub("(%d%d%d)", "%1,"):reverse()
	r = r:gsub("^,", "")
	return (n < 0 and "-" or "") .. r
end

function Util.fmtTime(sec)
	sec = math.max(0, math.floor(sec))
	return string.format("%02d:%02d:%02d", sec // 3600, (sec % 3600) // 60, sec % 60)
end

-- ลาก (เมาส์/ทัช) : onBegin(pos) / onMove(dx, dy, pos) / onEnd()
function Util.drag(handle, maid, onBegin, onMove, onEnd)
	local active, input, startPos = false, nil, nil
	maid:Give(handle.InputBegan:Connect(function(i)
		local t = i.UserInputType
		if t == Enum.UserInputType.MouseButton1 or t == Enum.UserInputType.Touch then
			active, input, startPos = true, i, i.Position
			if onBegin then onBegin(i.Position) end
			local c
			c = i.Changed:Connect(function()
				if i.UserInputState == Enum.UserInputState.End then
					active = false
					c:Disconnect()
					if onEnd then onEnd() end
				end
			end)
		end
	end))
	maid:Give(UIS.InputChanged:Connect(function(i)
		if not active then return end
		local isMouseMove = i.UserInputType == Enum.UserInputType.MouseMovement
			and input.UserInputType == Enum.UserInputType.MouseButton1
		if i == input or isMouseMove then
			local d = i.Position - startPos
			onMove(d.X, d.Y, i.Position)
		end
	end))
end

return Util

end
__mods["Pages/Dashboard"] = function()
-- แดชบอร์ด: แสดงเฉพาะข้อมูลจริงที่อ่านได้จากเกม/เครื่อง (ไม่มีข้อมูลจำลอง)
local Players = game:GetService("Players")
local RunService = game:GetService("RunService")
local Stats = game:GetService("Stats")
local Util = require("Core/Util")
local Theme = require("Core/Theme")
local Registry = require("Core/Registry")
local Log = require("Core/Log")
local Bus = require("Core/Bus")

local LP = Players.LocalPlayer

local function ping()
	local ok, v = pcall(function() return Stats.Network.ServerStatsItem["Data Ping"]:GetValue() end)
	return ok and v and string.format("%d ms", math.floor(v + 0.5)) or "UNKNOWN"
end

return {
	id = "dashboard", titleTh = "หน้าหลัก", titleEn = "Dashboard", order = 1,
	build = function(ctx)
		local C, maid, parent = ctx.C, ctx.maid, ctx.parent

		C.section(parent, "ผู้เล่น / เซิร์ฟเวอร์")
		local card = C.card(parent)
		C.stat(card, "ผู้เล่น", LP.DisplayName .. " (@" .. LP.Name .. ")")
		local setCash = C.stat(card, "เงิน (Cash)", "UNKNOWN")
		local setCount = C.stat(card, "ผู้เล่นในเซิร์ฟเวอร์", "")
		C.stat(card, "Place ID", tostring(game.PlaceId))
		C.stat(card, "Job ID", game.JobId ~= "" and (string.sub(game.JobId, 1, 8) .. "…") or "UNKNOWN")
		local setUp = C.stat(card, "เซิร์ฟเวอร์เปิดมาแล้ว", "")

		local function cash()
			local v = LP:GetAttribute("Cash")
			setCash(type(v) == "number" and Util.fmtNum(v) or "UNKNOWN")
		end
		cash()
		maid:Give(LP:GetAttributeChangedSignal("Cash"):Connect(cash))

		local function count()
			setCount(#Players:GetPlayers() .. " / " .. Players.MaxPlayers)
		end
		count()
		maid:Give(Players.PlayerAdded:Connect(count))
		maid:Give(Players.PlayerRemoving:Connect(function() task.defer(count) end))

		C.section(parent, "ประสิทธิภาพ")
		local perf = C.card(parent)
		local setFps = C.stat(perf, "FPS", "…")
		local setPing = C.stat(perf, "Ping", "…")
		local acc, frames = 0, 0
		maid:Give(RunService.Heartbeat:Connect(function(dt)
			acc += dt
			frames += 1
			if acc >= 1 then
				local fps = frames / acc
				setFps(string.format("%d", math.floor(fps + 0.5)), fps < 25 and Theme.warn or Theme.white)
				setPing(ping())
				setUp(Util.fmtTime(workspace.DistributedGameTime))
				acc, frames = 0, 0
			end
		end))

		C.section(parent, "AI Core")
		local core = C.card(parent)
		local setSys = C.stat(core, "ระบบที่ลงทะเบียน", "")
		local setOn = C.stat(core, "ระบบที่กำลังทำงาน", "")
		local function sys()
			setSys(tostring(#Registry.list()))
			setOn(tostring(Registry.countEnabled()))
		end
		sys()
		maid:Give(Bus.on("SystemChanged", sys))
		C.label(core, "ทุกระบบเริ่มต้นแบบ<b>ปิด</b> และเปิดแยกกันได้ ปุ่ม <b>STOP ALL</b> บนแถบหัวหยุดทุกระบบทันที")

		C.section(parent, "บันทึกล่าสุด")
		local logCard = C.card(parent)
		local logLabel = C.label(logCard, "")
		local function showLog()
			local lines = {}
			for _, e in ipairs(Log.recent(6)) do
				lines[#lines + 1] = string.format("%s  [%s] %s", os.date("%H:%M:%S", e.t), e.system, e.msg)
			end
			logLabel.Text = #lines > 0 and table.concat(lines, "\n") or "ยังไม่มีบันทึก"
		end
		showLog()
		maid:Give(Bus.on("Log", showLog))
	end,
}

end
__mods["Pages/Discord"] = function()
local Discord = require("Core/Discord")
local Notify = require("Core/Notify")

return {
	id = "discord", titleTh = "ดิสคอร์ด", titleEn = "Discord", order = 50,
	build = function(ctx)
		local C, parent = ctx.C, ctx.parent

		C.section(parent, "Webhook")
		local card = C.card(parent)
		local status = C.label(card, "")
		local function refresh()
			status.Text = Discord.hasUrl()
				and ("สถานะ: <font color='#39FF8C'><b>ตั้งค่าแล้ว</b></font>\n" .. Discord.mask())
				or "สถานะ: <font color='#FBBF24'><b>ยังไม่ได้ตั้ง</b></font>"
		end
		refresh()

		local box = C.input(parent, "วางลิงก์ Webhook ที่นี่ (https://discord.com/api/webhooks/...)")
		C.button(parent, "บันทึก Webhook", function()
			local ok, err = Discord.save(box.Text)
			if ok then
				box.Text = ""
				refresh()
				Notify.push({ title = "บันทึก Webhook แล้ว", text = "กด 'ส่งข้อความทดสอบ' เพื่อเช็กว่าใช้ได้", level = "ok" })
			else
				Notify.push({ title = "บันทึกไม่ได้", text = err, level = "warn", key = "dc_bad", cooldown = 2 })
			end
		end)
		C.button(parent, "ส่งข้อความทดสอบ", function()
			if not Discord.hasUrl() then
				Notify.push({ title = "ยังไม่ได้ตั้ง Webhook", level = "warn", key = "dc_none", cooldown = 2 })
				return
			end
			if not Discord.canSend() then
				Notify.push({ title = "ตัวรันไม่รองรับ HTTP", text = "ไม่มีฟังก์ชัน request/http_request", level = "crit", key = "dc_nohttp", cooldown = 5 })
				return
			end
			Discord.sendTest(function(ok, why)
				Notify.push(ok
					and { title = "ส่ง Discord สำเร็จ", level = "ok" }
					or { title = "ส่ง Discord ไม่สำเร็จ", text = tostring(why), level = "warn" })
			end)
		end, { style = "ghost" })
		C.button(parent, "ลบ Webhook", function()
			Discord.clear()
			refresh()
		end, { style = "danger" })

		C.section(parent, "ข้อควรระวัง")
		C.label(parent, "ลิงก์ Webhook เป็นความลับ ใครมีลิงก์นี้ส่งข้อความเข้าห้องของคุณได้ "
			.. "<b>อย่าแชร์สคริปต์หรือไฟล์ที่ตั้งค่าแล้ว</b> · ลิงก์ถูกเก็บในเครื่องคุณที่ <b>BALLKUN_V6/webhook.txt</b> "
			.. (Discord.canPersist() and "" or "(ตัวรันนี้ไม่รองรับไฟล์ → จำไว้แค่ในเซสชันนี้) ")
			.. "และจะไม่ถูกแสดงเต็มใน UI, แจ้งเตือน หรือบันทึก")
	end,
}

end
__mods["Pages/Notifications"] = function()
local Theme = require("Core/Theme")
local Notify = require("Core/Notify")
local Bus = require("Core/Bus")

local LV = { info = "INFO", ok = "OK", warn = "WARN", crit = "CRIT" }
local HEX = { info = "60A5FA", ok = "39FF8C", warn = "FBBF24", crit = "F85A5A" }

return {
	id = "notify", titleTh = "แจ้งเตือน", titleEn = "Alert Center", order = 90,
	build = function(ctx)
		local C, maid, parent = ctx.C, ctx.maid, ctx.parent
		local Config = require("Core/Config")
		C.slider(parent, { title = "เวลาแสดงป๊อปอัป", min = 0.5, max = 3, step = 0.25, value = Config.get("toastTime"),
			format = function(v) return string.format("x%.2f", v) end, onChange = function(v) Config.set("toastTime", v) end }, maid)
		C.slider(parent, { title = "จำนวนป๊อปอัปพร้อมกัน", min = 1, max = 6, step = 1, value = Config.get("toastMax"),
			format = function(v) return tostring(math.floor(v)) end, onChange = function(v) Config.set("toastMax", math.floor(v)) end }, maid)
		for _, lv in ipairs({ "info", "ok", "warn", "crit" }) do
			C.button(parent, "ทดสอบระดับ " .. string.upper(lv), function() Notify.push({ title = "ทดสอบ " .. lv, text = "ตัวอย่างการแจ้งเตือน", level = lv }) end, { style = "ghost" })
		end
		C.button(parent, "ล้างประวัติแจ้งเตือน", function() Notify.clear() end, { style = "ghost" })
		local card = C.card(parent)
		local list = C.label(card, "")
		local function render()
			local lines = {}
			for _, n in ipairs(Notify.history) do
				lines[#lines + 1] = string.format("<font color='#%s'><b>[%s·P%d]</b></font> %s  <b>%s</b> %s",
					HEX[n.level] or HEX.info, LV[n.level] or "INFO", n.priority, os.date("%H:%M:%S", n.time), n.title or "", n.text or "")
			end
			list.Text = #lines > 0 and table.concat(lines, "\n") or "ยังไม่มีการแจ้งเตือน"
		end
		render()
		maid:Give(Bus.on("Notify", render))
		maid:Give(Bus.on("NotifyCleared", render))
	end,
}

end
__mods["Pages/Piston"] = function()
local Players = game:GetService("Players")
local RunService = game:GetService("RunService")
local Util = require("Core/Util")
local Config = require("Core/Config")
local Registry = require("Core/Registry")
local Notify = require("Core/Notify")
local Bus = require("Core/Bus")
local Discord = require("Core/Discord")
local Piston = require("Systems/Piston")

local st = Piston.st
local ICON = { NEW = "🆕", SOLDOUT = "❌", PRICE = "💰", OPEN = "🟢", CLOSE = "🔒", SNAPSHOT = "📋" }

return {
	id = "piston", titleTh = "ร้านลูกสูบ 53–90", titleEn = "Piston Radar", order = 20,
	build = function(ctx)
		local C, maid, parent = ctx.C, ctx.maid, ctx.parent

		C.section(parent, "การควบคุม")
		local main
		main = C.toggle(parent, {
			title = "ติดตามร้านลูกสูบ", desc = "ฟังสัญญาณร้านเปิด/ปิด + อ่านสต็อกจากหน้าร้านของเกม (อ่านอย่างเดียว)",
			default = Registry.isEnabled("piston"),
			onChange = function(v)
				if not Registry.setEnabled("piston", v) then main.set(Registry.isEnabled("piston"), true) end
			end,
		})
		maid:Give(Bus.on("SystemChanged", function(id, on) if id == "piston" then main.set(on, true) end end))
		C.toggle(parent, { title = "เริ่มติดตามอัตโนมัติตอนรัน HUB", default = Config.get("pistonAutoStart"), onChange = function(v) Config.set("pistonAutoStart", v) end })
		C.toggle(parent, { title = "ส่ง Discord เมื่อร้านเปิด", desc = "พร้อมลิงก์เซิร์ฟเวอร์ รายการสินค้า ราคา เวลา", default = Config.get("pistonDiscordOpen"), onChange = function(v) Config.set("pistonDiscordOpen", v) end })
		C.toggle(parent, { title = "ส่ง Discord เมื่อร้านปิด", default = Config.get("pistonDiscordClose"), onChange = function(v) Config.set("pistonDiscordClose", v) end })
		C.toggle(parent, { title = "ส่ง Discord เมื่อสินค้า/ราคาเปลี่ยน", default = Config.get("pistonDiscordChange"), onChange = function(v) Config.set("pistonDiscordChange", v) end })
		C.toggle(parent, { title = "ใช้สัญญาณจุดร้านใน Workspace (ทดลอง)", desc = "ถ้าจุดร้านโผล่แล้วถือว่าเปิด — เปิดเมื่อยืนยันแล้วว่าตรงกับเกมจริง", default = Config.get("pistonSigSpot"), onChange = function(v) Config.set("pistonSigSpot", v) end })

		C.section(parent, "สถานะร้าน")
		local card = C.card(parent)
		local setState = C.stat(card, "สถานะ", "UNKNOWN")
		local setBy = C.stat(card, "ตรวจพบโดย", "-")
		local setAt = C.stat(card, "เวลาที่ตรวจพบ", "-")
		local setClose = C.stat(card, "ร้านปิดใน", "UNKNOWN")
		local setLoc = C.stat(card, "จุดร้าน (Workspace)", "UNKNOWN")
		local setDist = C.stat(card, "ระยะห่างจากคุณ", "UNKNOWN")

		local function refreshStatus()
			if st.open == true then setState("OPEN", Color3.fromRGB(57, 255, 140))
			elseif st.open == false then setState("CLOSED", Color3.fromRGB(248, 90, 90))
			else setState("UNKNOWN") end
			setBy(Piston.SRC[st.source] or "-")
			local t = st.open == true and st.openedAt or st.closedAt
			setAt(t and os.date("%H:%M:%S", t) or "-")
			local p = st.spotPos
			setLoc(p and string.format("%d, %d, %d", math.floor(p.X), math.floor(p.Y), math.floor(p.Z)) or "UNKNOWN")
			local ch = Players.LocalPlayer.Character
			local hrp = ch and ch:FindFirstChild("HumanoidRootPart")
			setDist((p and hrp) and string.format("%d studs", math.floor((hrp.Position - p).Magnitude)) or "UNKNOWN")
		end
		local acc = 0
		maid:Give(RunService.Heartbeat:Connect(function(dt)
			acc += dt
			if acc < 1 then return end
			acc = 0
			local rem = st.closesAt and (st.closesAt - os.time()) or nil
			setClose((st.open == true and rem and rem > 0) and Util.fmtTime(rem):sub(4) or "UNKNOWN")
			refreshStatus()
		end))

		C.button(parent, "สแกนหน้าร้านตอนนี้", function()
			local ok, why = Piston.scanNow()
			Notify.push(ok and { title = "อ่านหน้าร้านสำเร็จ", level = "ok", key = "pscan", cooldown = 2 }
				or { title = "สแกนไม่ได้", text = why, level = "warn", key = "pscan", cooldown = 2 })
		end, { style = "ghost" })
		C.button(parent, "ส่งสถานะร้านไป Discord ตอนนี้", function()
			if not Discord.hasUrl() then
				Notify.push({ title = "ยังไม่ได้ตั้ง Webhook", text = "ไปที่เมนู ดิสคอร์ด", level = "warn", key = "pnohook", cooldown = 3 })
				return
			end
			Piston.sendStatus(function(ok, why)
				Notify.push(ok and { title = "ส่งสถานะแล้ว", level = "ok" } or { title = "ส่ง Discord ไม่สำเร็จ", text = tostring(why), level = "warn" })
			end)
		end)

		C.section(parent, "สินค้า 53–90 (38 เบอร์)")
		local listCard = C.card(parent)
		local list = C.label(listCard, "")
		local function renderList()
			local lines = {}
			for _, s in ipairs(Piston.SIZES) do
				local it = st.items[s]
				local line
				if not it then line = string.format("<b>%d</b>  UNKNOWN", s)
				elseif it.status == "AVAILABLE" then
					line = string.format("<font color='#39FF8C'><b>%d</b>  %s  ·  เหลือ %s</font>", s, it.price and Util.fmtNum(it.price) or "UNKNOWN", it.left and tostring(it.left) or "UNKNOWN")
				elseif it.status == "SOLDOUT" then
					line = string.format("<font color='#F85A5A'><b>%d</b>  หมด</font>", s)
				elseif it.status == "NOT_SOLD" then
					line = string.format("<font color='#6B7F76'>%d  ไม่มีขายในเกม</font>", s)
				else
					line = string.format("<font color='#FBBF24'><b>%d</b>  UNKNOWN</font>%s", s, it.price and ("  (ราคาตามเกม " .. Util.fmtNum(it.price) .. ")") or "")
				end
				lines[#lines + 1] = line
			end
			list.Text = table.concat(lines, "\n")
		end
		C.label(listCard, "ราคา/สต็อกจริงอ่านได้เมื่อเปิดหน้าร้านของเกมเท่านั้น · UNKNOWN = ยังไม่มีข้อมูลจริง", { size = 11 })

		C.section(parent, "ประวัติร้านและราคา")
		local histCard = C.card(parent)
		local hist = C.label(histCard, "")
		local function renderHist()
			local lines = {}
			for i = 1, math.min(10, #Piston.history) do
				local e = Piston.history[i]
				local what
				if e.type == "NEW" then what = string.format("เบอร์ %d เข้า (เหลือ %s)", e.size, tostring(e.new))
				elseif e.type == "SOLDOUT" then what = string.format("เบอร์ %d หมด", e.size)
				elseif e.type == "PRICE" then what = string.format("เบอร์ %d ราคา %s→%s", e.size, Util.fmtNum(e.old or 0), Util.fmtNum(e.new or 0))
				elseif e.type == "OPEN" then what = "ร้านเปิด"
				elseif e.type == "CLOSE" then what = "ร้านปิด"
				else what = "สแนปช็อต: " .. tostring(e.data or "") end
				lines[#lines + 1] = string.format("%s %s  %s", ICON[e.type] or "•", os.date("%H:%M:%S", e.t), what)
			end
			hist.Text = #lines > 0 and table.concat(lines, "\n") or "ยังไม่มีประวัติ"
		end
		C.button(parent, "ล้างประวัติร้าน", function() Piston.clearHistory() end, { style = "ghost" })

		C.section(parent, "วินิจฉัยสัญญาณ (เกมส่งอะไรมาจริง)")
		local diagCard = C.card(parent)
		local diag = C.label(diagCard, "")
		local function renderDiag()
			local lines = {}
			for _, s in ipairs(Piston.signals) do
				lines[#lines + 1] = string.format("%s  <b>%s</b>  %s", os.date("%H:%M:%S", s.t), s.name, s.info)
			end
			diag.Text = #lines > 0 and table.concat(lines, "\n") or "ยังไม่ได้รับสัญญาณ (เปิดระบบติดตามไว้แล้วรอร้านเปิด)"
		end

		local function all() refreshStatus() renderList() renderHist() renderDiag() end
		all()
		maid:Give(Bus.on("PistonUpdate", all))
	end,
}

end
__mods["Pages/Server"] = function()
-- ลิงก์เซิร์ฟเวอร์: ดู/คัดลอก/ส่งเข้า Discord + วางลิงก์เซิร์ฟส่วนตัว
local Discord = require("Core/Discord")
local Notify = require("Core/Notify")
local Config = require("Core/Config")
local Bus = require("Core/Bus")

return {
	id = "server", titleTh = "ลิงก์เซิร์ฟ", titleEn = "Server Link", order = 15,
	build = function(ctx)
		local C, maid, parent = ctx.C, ctx.maid, ctx.parent

		C.section(parent, "เซิร์ฟเวอร์ที่คุณอยู่")
		local card = C.card(parent)
		local setKind = C.stat(card, "ชนิดเซิร์ฟ", "")
		local setJob = C.stat(card, "Job ID", "")
		local linkLabel = C.label(card, "")
		local function refresh()
			local link, kind = Discord.serverLink()
			setKind(kind == "private" and "ส่วนตัว (PRIVATE)" or "สาธารณะ (PUBLIC)")
			setJob(game.JobId ~= "" and game.JobId or "UNKNOWN")
			if link then
				linkLabel.Text = "<b>ลิงก์:</b> " .. link:gsub("&", "&amp;")
			elseif kind == "private" then
				linkLabel.Text = "<font color='#FBBF24'><b>ไม่มีลิงก์</b></font> — คุณอยู่เซิร์ฟส่วนตัว Roblox ไม่ให้สคริปต์อ่านโค้ดเชิญ ต้องวางลิงก์เชิญด้านล่างเอง"
			else
				linkLabel.Text = "<font color='#FBBF24'><b>UNKNOWN</b></font> — อ่าน Job ID ไม่ได้ (อาจอยู่ใน Studio)"
			end
		end
		refresh()
		maid:Give(Bus.on("LinkChanged", refresh))

		C.button(parent, "คัดลอกลิงก์", function()
			local link = Discord.serverLink()
			if not link then Notify.push({ title = "ยังไม่มีลิงก์ให้คัดลอก", level = "warn", key = "nolink", cooldown = 2 }) return end
			local fn = setclipboard or toclipboard or (syn and syn.write_clipboard)
			if type(fn) ~= "function" then
				Notify.push({ title = "ตัวรันไม่รองรับคัดลอก", text = "ลิงก์แสดงอยู่ในการ์ดด้านบน", level = "warn", key = "noclip", cooldown = 3 })
				return
			end
			pcall(fn, link)
			Notify.push({ title = "คัดลอกลิงก์แล้ว", level = "ok", key = "copied", cooldown = 1 })
		end)
		C.button(parent, "ส่งลิงก์นี้เข้า Discord ตอนนี้", function()
			if not Discord.hasUrl() then Notify.push({ title = "ยังไม่ได้ตั้ง Webhook", text = "ไปที่เมนู ดิสคอร์ด", level = "warn", key = "dc_none", cooldown = 2 }) return end
			Discord.sendLink(function(ok, why)
				if ok then Notify.push({ title = "ส่งลิงก์เซิร์ฟเข้า Discord แล้ว", level = "ok" })
				elseif why then Notify.push({ title = "ส่งไม่ได้", text = tostring(why), level = "warn", key = "linkfail", cooldown = 3 }) end
			end)
		end, { style = "ghost" })

		C.section(parent, "ลิงก์เซิร์ฟส่วนตัว")
		local pcard = C.card(parent)
		local status = C.label(pcard, "")
		local function showP()
			local has = (Config.get("privateLink") or "") ~= ""
			status.Text = has and "สถานะ: <font color='#39FF8C'><b>บันทึกแล้ว</b></font> (ใช้เมื่อคุณอยู่เซิร์ฟส่วนตัวเท่านั้น)" or "สถานะ: <font color='#FBBF24'><b>ยังไม่ได้ตั้ง</b></font>"
		end
		showP()
		local box = C.input(pcard, "วางลิงก์เชิญเซิร์ฟส่วนตัว (https://www.roblox.com/...)")
		C.button(pcard, "บันทึกลิงก์เซิร์ฟส่วนตัว", function()
			local ok, err = Discord.setPrivateLink(box.Text)
