		end)
		C.button(pcard, "ลบลิงก์เซิร์ฟส่วนตัว", function() Discord.clearPrivateLink() showP() end, { style = "danger" })
		C.label(parent, "ลิงก์เซิร์ฟส่วนตัวใครมีก็เข้าได้ — เก็บในเครื่องคุณที่ <b>BALLKUN_V6/config.json</b> อย่าแชร์ไฟล์นี้ · ตอนร้านลูกสูบเปิด HUB จะส่งลิงก์ที่ใช้ได้เข้า Discord ให้อัตโนมัติ")
	end,
}

