__mods["Pages/Systems"] = function()
-- ศูนย์ระบบ: สวิตช์เปิด/ปิดของทุกระบบที่ทำเสร็จจริง + สถานะระบบที่ยังไม่ได้ทำ (ไม่มีปุ่มหลอก)
local Registry = require("Core/Registry")
local Bus = require("Core/Bus")
local Theme = require("Core/Theme")

-- ระบบที่วางแผนไว้แต่ยังไม่ได้เขียน (แสดงเป็นข้อความเท่านั้น)
local PLANNED = {
	{ "Auto Farm (MONITOR)", "ติดตามงาน/รายได้ ไม่ยุ่งกับ FarmCheck" },
	{ "Auto Delivery (นำทาง)", "อ่านจุดหมายจาก DeliveryClient" },
	{ "Vehicle Intelligence", "ความเร็ว น้ำมัน สภาพรถ" },
	{ "Auto Fuel / Repair", "แจ้งเตือน + นำทางไปปั๊ม/อู่" },
	{ "Smart Navigation", "แผนที่ มินิแมป GPS" },
	{ "Racing", "สถานะสนาม นับถอยหลัง ผลการแข่ง" },
	{ "Dyno & Tune", "อ่านข้อมูลจากหน้า Dyno/Tune" },
}

return {
	id = "systems", titleTh = "ศูนย์ระบบ", titleEn = "Systems", order = 2,
	build = function(ctx)
		local C, maid, parent = ctx.C, ctx.maid, ctx.parent

		C.section(parent, "ระบบที่พร้อมใช้งาน")
		local toggles = {}
		for _, def in ipairs(Registry.list()) do
			local t = C.toggle(parent, {
				title = (def.nameTh or def.id) .. "  ·  " .. (def.nameEn or ""),
				desc = "เปิด/ปิดแยกจากระบบอื่น",
				default = def.enabled,
				onChange = function(on)
					local ok = Registry.setEnabled(def.id, on)
					if not ok and toggles[def.id] then toggles[def.id].set(Registry.isEnabled(def.id), true) end
				end,
			})
			toggles[def.id] = t
		end
		if #Registry.list() == 0 then C.label(parent, "ยังไม่มีระบบลงทะเบียน") end

		-- ซิงก์สวิตช์เมื่อระบบถูกเปิด/ปิดจากที่อื่น (เช่น STOP ALL)
		maid:Give(Bus.on("SystemChanged", function(id, on)
			if toggles[id] and toggles[id].get() ~= on then toggles[id].set(on, true) end
		end))

		C.button(parent, "■ หยุดทุกระบบ", function() Registry.stopAll("กดจากศูนย์ระบบ") end, { style = "danger" })

		C.section(parent, "ยังไม่ได้พัฒนา (ตามลำดับเฟส)")
		local card = C.card(parent)
		local lines = {}
		for _, p in ipairs(PLANNED) do
			lines[#lines + 1] = string.format("<font color='#FBBF24'>○</font> <b>%s</b> — %s", p[1], p[2])
		end
		C.label(card, table.concat(lines, "\n"))
		C.label(card, "ระบบเหล่านี้ยังไม่มีโค้ด จึงไม่มีปุ่มให้กด จะเพิ่มเมนูของระบบนั้นเมื่อทำเสร็จและทดสอบแล้ว")
	end,
}

end
__mods["Pages/Theme"] = function()
-- ปรับธีม: สี / ฟอนต์ / ขนาดตัวอักษร / ภาพพื้นหลัง  (กด "ใช้ธีม" เพื่อสร้าง UI ใหม่ตามค่าที่ตั้ง)
local Config = require("Core/Config")
local Theme = require("Core/Theme")
local Notify = require("Core/Notify")
local Hub = require("UI/Hub")

local ACCENTS = { "39FF8C", "00E5FF", "B26BFF", "FF4D6D", "FFC83D", "FF7A1A", "FFFFFF" }
local PANELS = { "08110D", "0A0A12", "140A0A", "0D0D0D", "0B1220", "120B1F" }
local KEYS = {
	{ "accentColor", "สีหลัก (Neon)", ACCENTS },
	{ "panelColor", "สีพื้นหน้าต่าง", PANELS },
	{ "textColor", "สีตัวอักษรหลัก", { "FFFFFF", "E6FFF2", "FFF3C4", "D6E4FF" } },
	{ "dimColor", "สีตัวอักษรรอง", { "A0BEAF", "9AA5B1", "C9B8A0", "8FB8C9" } },
}

local function applyNow()
	Theme.apply(Config.data)
	task.defer(Hub.rebuild)
end

return {
	id = "theme", titleTh = "ธีม / ฟอนต์", titleEn = "Theme", order = 95,
	build = function(ctx)
		local C, maid, parent = ctx.C, ctx.maid, ctx.parent

		C.section(parent, "สี")
		for _, k in ipairs(KEYS) do
			local key, title, list = k[1], k[2], k[3]
			local card = C.card(parent)
			C.label(card, "<b>" .. title .. "</b> — แตะสี หรือพิมพ์ HEX 6 หลัก (เช่น 39FF8C)")
			local box = C.input(card, "HEX เช่น 39FF8C")
			box.Text = tostring(Config.get(key))
			local function setHex(h)
				h = tostring(h):gsub("^#", ""):upper()
				if not Theme.isHex(h) then
					Notify.push({ title = "HEX ไม่ถูกต้อง", text = "ต้องเป็นตัวเลข/A-F 6 หลัก", level = "warn", key = "badhex", cooldown = 2 })
					box.Text = tostring(Config.get(key))
					return
				end
				Config.set(key, h)
				box.Text = h
			end
			box.FocusLost:Connect(function() setHex(box.Text) end)
			C.swatches(card, list, setHex)
		end

		C.section(parent, "ฟอนต์")
		local fcard = C.card(parent)
		local cur = C.label(fcard, "")
		local function showFont() cur.Text = "ฟอนต์ที่เลือก: <b>" .. tostring(Config.get("fontId")) .. "</b> (ไทยบางฟอนต์ใช้ฟอนต์สำรองของ Roblox)" end
		showFont()
		for _, f in ipairs(Theme.FONTS) do
			local b = C.button(fcard, f.name .. "  —  BALL KUN 123", function() Config.set("fontId", f.id) showFont() end, { style = "ghost" })
			b.Font = f.bold
		end
		C.slider(parent, {
			title = "ขนาดตัวอักษร", min = 0.8, max = 1.3, step = 0.05, value = Config.get("fontScale"),
			format = function(v) return string.format("%d%%", math.floor(v * 100 + 0.5)) end,
			onChange = function(v) Config.set("fontScale", v) end,
		}, maid)

		C.button(parent, "✔ ใช้ธีม (สร้าง UI ใหม่)", applyNow)
		C.button(parent, "คืนค่าสี/ฟอนต์เริ่มต้น", function()
			local d = Config.defaults
			for _, key in ipairs({ "accentColor", "panelColor", "textColor", "dimColor", "fontId", "fontScale" }) do Config.set(key, d[key]) end
			applyNow()
		end, { style = "ghost" })

		C.section(parent, "ภาพพื้นหลัง")
		C.toggle(parent, {
			title = "แสดงภาพพื้นหลัง", desc = "ต้องใช้ตัวรันที่รองรับ writefile + getcustomasset (ภาพเริ่มต้นฝังในสคริปต์แล้ว)",
			default = Config.get("bgEnabled"),
			onChange = function(v) Config.set("bgEnabled", v) task.defer(Hub.rebuild) end,
		})
		C.slider(parent, {
			title = "ความชัดของภาพ", min = 0.1, max = 1, step = 0.05, value = Config.get("bgVisible"),
			format = function(v) return string.format("%d%%", math.floor(v * 100 + 0.5)) end,
			onChange = function(v) Config.set("bgVisible", v) end,
		}, maid)
		local bcard = C.card(parent)
		C.label(bcard, "ใช้ภาพของคุณเอง 2 วิธี: ① วาง Asset ID ของรูปที่อัปโหลดเป็น Decal/Image ใน Roblox ② วางไฟล์ <b>bg.jpg</b> หรือ <b>bg.png</b> ในโฟลเดอร์ <b>BALLKUN_V6</b> ของตัวรัน")
		local box = C.input(bcard, "Asset ID (ตัวเลข)")
		box.Text = tostring(Config.get("bgAsset"))
		C.button(bcard, "ใช้ภาพจาก Asset ID นี้", function()
			local id = box.Text:match("%d+")
			if not id then Notify.push({ title = "ต้องเป็นตัวเลข Asset ID", level = "warn", key = "badasset", cooldown = 2 }) return end
			Config.set("bgAsset", id)
			task.defer(Hub.rebuild)
		end)
		C.button(bcard, "กลับไปใช้ภาพต้นฉบับ", function() Config.set("bgAsset", "") task.defer(Hub.rebuild) end, { style = "ghost" })
	end,
}

end
__mods["Systems/Piston"] = function()
-- Piston Shop Intelligence (อ่านอย่างเดียว ไม่เรียก Remote ของเกม)
-- สัญญาณ "ร้านเปิด": หน้าร้านของเกม / อีเวนต์ PistonOpen / ประกาศ (Notify,Notice,Announce) / จุดร้านใน Workspace (ทดลอง)
-- ข้อมูลสินค้า: อ่านจากหน้าร้านของเกม (PlayerGui.PistonShop) + ราคาตาม PistonShared ถ้าอ่านได้ ที่เหลือ = UNKNOWN
local Players = game:GetService("Players")
local RS = game:GetService("ReplicatedStorage")
local HttpService = game:GetService("HttpService")
local Util = require("Core/Util")
local Maid = require("Core/Maid")
local Bus = require("Core/Bus")
local Log = require("Core/Log")
local Notify = require("Core/Notify")
local Config = require("Core/Config")
local Discord = require("Core/Discord")

local LP = Players.LocalPlayer
local SIZES, SIZESET = {}, {}
for s = 53, 90 do SIZES[#SIZES + 1] = s SIZESET[s] = true end

local SRC = {
	window = "หน้าร้านของเกม", event = "อีเวนต์ PistonOpen", spot = "จุดร้านใน Workspace (ทดลอง)",
	notice = "ประกาศในเกม", timer = "ตัวจับเวลาของร้าน",
}

local P = { SIZES = SIZES, SRC = SRC, running = false, signals = {}, history = {} }
P.st = {
	open = nil, source = nil, openedAt = nil, closedAt = nil, closesAt = nil, lastRemaining = nil,
	spotPos = nil, items = {}, scanned = false, baseline = false, sentOpen = false,
}
local st = P.st
local maid, scanToken = nil, 0
local pending, flushScheduled, lastChangeSent, lastOpenSent = {}, false, 0, -1e9
local gp -- cache ตารางราคาของเกม (false = อ่านไม่ได้)

----------------------------------------------------------------- ข้อมูลราคาของเกม
local function gamePrices()
	if gp ~= nil then return gp or nil end
	local ok, res = pcall(function()
		local m = RS:FindFirstChild("PistonShared")
		if not m then return nil end
		local rq = __roblox_require or require
		local out = {}
		for k, v in pairs(rq(m).PRICES) do
			if tonumber(k) and tonumber(v) then out[tonumber(k)] = tonumber(v) end
		end
		return out
	end)
	gp = (ok and res) or false
	return ok and res or nil
end

local function classify(size, f)
	local g = gamePrices()
	local it = {}
	it.price = (f and f.price) or (g and g[size]) or nil
	it.priceSrc = (f and f.price) and "GUI" or (it.price and "GAME" or nil)
	if f then
		it.left = f.left
		it.status = f.left == nil and "UNKNOWN" or (f.left > 0 and "AVAILABLE" or "SOLDOUT")
	else
		it.status = (g and not g[size]) and "NOT_SOLD" or "UNKNOWN"
	end
	return it
end

local function resetItems()
	st.items = {}
	for _, s in ipairs(SIZES) do st.items[s] = classify(s, nil) end
	st.scanned, st.baseline = false, false
end

----------------------------------------------------------------- ประวัติ (ไฟล์ในเครื่อง)
local HFILE, HDIR = "BALLKUN_V6/piston_history.json", "BALLKUN_V6"
local function canFile() return type(isfile) == "function" and type(readfile) == "function" and type(writefile) == "function" end
local saveQueued = false
local function saveHistory()
	if not canFile() or saveQueued then return end
	saveQueued = true
	task.delay(1.5, function()
		saveQueued = false
		pcall(function()
			if type(isfolder) == "function" and type(makefolder) == "function" and not isfolder(HDIR) then makefolder(HDIR) end
			writefile(HFILE, HttpService:JSONEncode(P.history))
		end)
	end)
end

function P.load()
	if not canFile() then return end
	local ok, raw = pcall(function() return isfile(HFILE) and readfile(HFILE) or nil end)
	if ok and raw then
		local ok2, t = pcall(HttpService.JSONDecode, HttpService, raw)
		if ok2 and type(t) == "table" then P.history = t end
	end
end

local function record(ev)
	ev.t = os.time()
	table.insert(P.history, 1, ev)
	while #P.history > 150 do table.remove(P.history) end
	saveHistory()
	Bus.fire("PistonUpdate")
end

local function describe(...)
	local out = {}
	for i = 1, math.min(select("#", ...), 4) do
		local v = select(i, ...)
		local t = typeof(v)
		out[#out + 1] = t == "string" and ('"' .. v:sub(1, 80) .. '"') or ("<" .. t .. ">")
	end
	return table.concat(out, ", ")
end

local function addSignal(name, info)
	table.insert(P.signals, 1, { t = os.time(), name = name, info = info })
	while #P.signals > 12 do table.remove(P.signals) end
	Bus.fire("PistonUpdate")
end

----------------------------------------------------------------- Discord
local function buildPayload(title, color, withProducts, t)
	t = t or os.time()
	local link = Discord.serverLink()
	local fields = {
		{ name = "🏪 SHOP", value = "MAHANAKHON RACING", inline = true },
		{ name = "👥 PLAYERS", value = #Players:GetPlayers() .. "/" .. Players.MaxPlayers, inline = true },
		{ name = "📡 DETECTED BY", value = SRC[st.source] or "UNKNOWN", inline = true },
		{ name = "🌐 SERVER LINK", value = link or "UNKNOWN" },
	}
	if withProducts then
		local avail, prices = {}, {}
		if st.scanned then
			for _, s in ipairs(SIZES) do
				local it = st.items[s]
				if it and it.status == "AVAILABLE" then
					avail[#avail + 1] = string.format("`%d` เหลือ %s", s, it.left and tostring(it.left) or "UNKNOWN")
					prices[#prices + 1] = string.format("`%d` = %s", s, it.price and Util.fmtNum(it.price) or "UNKNOWN")
				end
			end
			fields[#fields + 1] = { name = "📦 PRODUCT AVAILABLE", value = #avail > 0 and table.concat(avail, "\n") or "ไม่มีสินค้า (หมดทุกเบอร์)", inline = true }
			fields[#fields + 1] = { name = "💰 PRICE", value = #prices > 0 and table.concat(prices, "\n") or "-", inline = true }
		else
			fields[#fields + 1] = { name = "📦 PRODUCT AVAILABLE", value = "UNKNOWN (ยังไม่ได้อ่านหน้าร้านของเกม)", inline = true }
			local g, lines = gamePrices(), {}
			if g then
				for _, s in ipairs(SIZES) do if g[s] then lines[#lines + 1] = string.format("`%d` = %s", s, Util.fmtNum(g[s])) end end
			end
			fields[#fields + 1] = { name = "💰 PRICE", value = #lines > 0 and ("ตามตารางราคาเกม (ยังไม่ยืนยันสต็อก)\n" .. table.concat(lines, "\n")) or "UNKNOWN", inline = true }
		end
		local rem = st.closesAt and (st.closesAt - os.time()) or nil
		fields[#fields + 1] = { name = "⏳ CLOSES IN", value = (rem and rem > 0) and Util.fmtTime(rem):sub(4) or "UNKNOWN", inline = true }
		local p = st.spotPos
		fields[#fields + 1] = { name = "📍 LOCATION", value = p and string.format("%d, %d, %d", math.floor(p.X), math.floor(p.Y), math.floor(p.Z)) or "UNKNOWN", inline = true }
	end
	fields[#fields + 1] = { name = "⏰ DETECTED TIME", value = string.format("<t:%d:F> (<t:%d:R>)", t, t) }
	return {
		content = link and ("**" .. title .. "**\n<" .. link .. ">") or title,
		embeds = { { title = title, url = link, color = color, fields = fields,
			footer = { text = "BALL KUN HUB V6" }, timestamp = os.date("!%Y-%m-%dT%H:%M:%SZ", t) } },
	}
end

local function sendOpen()
	if st.sentOpen then return end
	st.sentOpen = true
	if not Config.get("pistonDiscordOpen") then return end
	if not Discord.hasUrl() then
		Notify.push({ title = "ร้านเปิด แต่ยังไม่ได้ตั้ง Webhook", text = "ไปที่เมนู ดิสคอร์ด เพื่อใส่ลิงก์", level = "warn", key = "piston_nohook", cooldown = 120 })
		return
	end
	if os.clock() - lastOpenSent < 90 then return end -- กันส่งซ้ำเมื่อสัญญาณกระพริบ
	lastOpenSent = os.clock()
	if not Discord.serverLink() then
		Notify.push({ key = "piston_nolink", cooldown = 120, level = "warn", title = "ไม่มีลิงก์เซิร์ฟเวอร์",
			text = Discord.isPrivateServer() and "คุณอยู่เซิร์ฟส่วนตัว วางลิงก์ในเมนู ลิงก์เซิร์ฟ" or "อ่าน Job ID ไม่ได้" })
	end
	Discord.send(buildPayload("🚨 PISTON SHOP OPENED", 0x39FF8C, true, st.openedAt), function(ok)
		if ok then Notify.push({ title = "ส่งลิงก์ร้านเปิดเข้า Discord แล้ว", level = "ok", key = "piston_sent", cooldown = 5 }) end
	end)
end

function P.sendClosed()
	if Config.get("pistonDiscordClose") and Discord.hasUrl() then
		Discord.send(buildPayload("🔒 PISTON SHOP CLOSED", 0xFF4D4D, false))
	end
end

function P.sendStatus(cb)
	local label = st.open == true and "OPEN" or (st.open == false and "CLOSED" or "UNKNOWN")
	return Discord.send(buildPayload("📋 PISTON SHOP STATUS: " .. label, 0x60A5FA, true, os.time()), cb)
end

local function changePayload(evs)
	local lines = {}
	for i, e in ipairs(evs) do
		if i > 20 then break end
		if e.type == "NEW" then
			lines[#lines + 1] = string.format("🆕 `%d` เข้าสต็อก · เหลือ %s · ราคา %s", e.size, e.new and tostring(e.new) or "UNKNOWN", e.price and Util.fmtNum(e.price) or "UNKNOWN")
		elseif e.type == "SOLDOUT" then
			lines[#lines + 1] = string.format("❌ `%d` หมด", e.size)
		elseif e.type == "PRICE" then
			lines[#lines + 1] = string.format("💰 `%d` ราคา %s → %s", e.size, Util.fmtNum(e.old), Util.fmtNum(e.new))
		end
	end
	local link = Discord.serverLink()
	return { embeds = { {
		title = "📦 PISTON SHOP UPDATE", color = 0xFBBF24, description = table.concat(lines, "\n"),
		fields = { { name = "🌐 SERVER LINK", value = link or "UNKNOWN" }, { name = "⏰ TIME", value = string.format("<t:%d:F>", os.time()) } },
		footer = { text = "BALL KUN HUB V6" },
	} } }
end

local function queueChange(ev)
	table.insert(pending, ev)
	if flushScheduled then return end
	flushScheduled = true
	task.delay(math.max(6, 20 - (os.clock() - lastChangeSent)), function()
		flushScheduled = false
		local evs = pending
		pending = {}
		if #evs == 0 or not Config.get("pistonDiscordChange") or not Discord.hasUrl() then return end
		lastChangeSent = os.clock()
		Discord.send(changePayload(evs))
	end)
end

----------------------------------------------------------------- สถานะเปิด/ปิด
local function setOpen(on, src)
	if on then
		if st.open == true then return end
		st.open, st.source, st.openedAt, st.closedAt = true, src, os.time(), nil
		st.sentOpen = false
		resetItems()
		record({ type = "OPEN", src = src })
		Log.write("piston", "ok", "ร้านลูกสูบเปิด (" .. src .. ")")
		Notify.push({ title = "ร้านลูกสูบเปิดแล้ว", text = "ตรวจพบโดย: " .. (SRC[src] or src), level = "ok", priority = 3, key = "piston_open", cooldown = 20, system = "piston" })
		task.delay(4, function() -- ถ้ายังไม่ได้อ่านหน้าร้าน ส่งแบบ UNKNOWN
			if P.running and st.open == true and not st.sentOpen then sendOpen() end
		end)
	else
		if st.open ~= true then return end
		st.open, st.source, st.closedAt, st.closesAt = false, src, os.time(), nil
		record({ type = "CLOSE", src = src })
		Log.write("piston", "warn", "ร้านลูกสูบปิด (" .. src .. ")")
		Notify.push({ title = "ร้านลูกสูบปิดแล้ว", text = "ตรวจพบโดย: " .. (SRC[src] or src), level = "warn", priority = 3, key = "piston_close", cooldown = 20, system = "piston" })
		P.sendClosed()
	end
	Bus.fire("PistonUpdate")
end

----------------------------------------------------------------- อ่านหน้าร้านของเกม
local function getWindow()
	local pg = LP:FindFirstChild("PlayerGui")
	local g = pg and pg:FindFirstChild("PistonShop")
	local w = g and g:FindFirstChild("PistonShopWindow")
	return w, g
end

local function windowOpen()
	local w, g = getWindow()
	return (w ~= nil and w.Visible and g.Enabled), w
end

local function strip(s) return (tostring(s):gsub("<[^>]+>", "")) end

local function readWindow(win)
	local found, n = {}, 0
	local body = win:FindFirstChild("Body")
	local list = body and body:FindFirstChildOfClass("ScrollingFrame")
	if not list then return found, nil, 0 end
	for _, card in ipairs(list:GetChildren()) do
		if card:IsA("GuiObject") then
			local size, left, price
			for _, d in ipairs(card:GetDescendants()) do
				if d:IsA("TextLabel") or d:IsA("TextButton") then
					local t = strip(d.Text):match("^%s*(.-)%s*$")
					local num = t:match("^(%d+)$")
					if num and SIZESET[tonumber(num)] and not size then size = tonumber(num) end
					local l = t:match("เหลือ%s*(%d+)")
					if l then left = tonumber(l) elseif t:find("หมด", 1, true) then left = 0 end
					if (d:IsA("TextButton") or d:FindFirstAncestorWhichIsA("GuiButton")) and not t:find("หมด", 1, true) then
						local digits = t:match("([%d,]+)%s*$")
						local v = digits and tonumber((digits:gsub(",", "")))
						if v and v >= 100 then price = v end
					end
				end
			end
			if size and (left ~= nil or price) then
				found[size] = { left = left, price = price }
				n += 1
			end
		end
	end
	local remaining
	local hdr = win:FindFirstChild("Header")
	local sub = hdr and hdr:FindFirstChild("Sub")
	if sub then
		local m, s = strip(sub.Text):match("ปิดใน%s*(%d+):(%d+)")
		if m then remaining = tonumber(m) * 60 + tonumber(s) end
	end
	return found, remaining, n
end

local function applySnapshot(found, remaining)
	if st.open == true and remaining and st.lastRemaining and remaining > st.lastRemaining + 10 then
		st.open = false -- ร้านรอบใหม่ (ย้ายร้าน/รีสต็อก)
	end
	if st.open ~= true then setOpen(true, "window") end
	if remaining then
		st.closesAt = os.time() + remaining
		st.lastRemaining = remaining
	end
	local new, events, old = {}, {}, st.items
	for _, s in ipairs(SIZES) do new[s] = classify(s, found[s]) end
	local first = not st.baseline
	if not first then
		for _, s in ipairs(SIZES) do
			local o, n = old[s], new[s]
			if o and n then
				if n.status == "AVAILABLE" and (o.status ~= "AVAILABLE" or (o.left and n.left and n.left > o.left)) then
					events[#events + 1] = { type = "NEW", size = s, old = o.left, new = n.left, price = n.price }
				elseif n.status == "SOLDOUT" and o.status == "AVAILABLE" then
					events[#events + 1] = { type = "SOLDOUT", size = s, old = o.left, new = 0 }
				end
				if o.priceSrc == "GUI" and n.priceSrc == "GUI" and o.price ~= n.price then
					events[#events + 1] = { type = "PRICE", size = s, old = o.price, new = n.price }
				end
			end
		end
	end
	st.items, st.scanned, st.baseline = new, true, true
	if first then
		local parts = {}
		for _, s in ipairs(SIZES) do
			local it = new[s]
			if it.status == "AVAILABLE" or it.status == "SOLDOUT" then
				parts[#parts + 1] = string.format("%d:%s×%s", s, it.price and tostring(it.price) or "?", it.left and tostring(it.left) or "?")
			end
		end
		record({ type = "SNAPSHOT", data = table.concat(parts, " ") })
	end
	for _, e in ipairs(events) do
		e.src = "window"
		record(e)
		if e.type == "NEW" then
			Notify.push({ title = "สินค้าเข้าใหม่: ลูกสูบเบอร์ " .. e.size, text = "เหลือ " .. tostring(e.new) .. (e.price and (" · ราคา " .. Util.fmtNum(e.price)) or ""), level = "ok", priority = 2, key = "pn" .. e.size, cooldown = 15, system = "piston" })
		elseif e.type == "SOLDOUT" then
			Notify.push({ title = "ลูกสูบเบอร์ " .. e.size .. " หมด", level = "info", priority = 1, key = "ps" .. e.size, cooldown = 30, system = "piston" })
		else
			Notify.push({ title = "ราคาเปลี่ยน: เบอร์ " .. e.size, text = Util.fmtNum(e.old) .. " → " .. Util.fmtNum(e.new), level = "warn", priority = 3, key = "pp" .. e.size, cooldown = 15, system = "piston" })
		end
		queueChange(e)
	end
	if st.open == true and not st.sentOpen then sendOpen() end
	Bus.fire("PistonUpdate")
end

local function onWindowHidden()
	if st.open ~= true or not st.closesAt then return end
	local rem = st.closesAt - os.time()
	if rem <= 3 then setOpen(false, "timer") return end
	local mark = st.closesAt
	task.delay(rem + 2, function()
		if P.running and st.open == true and st.closesAt == mark then setOpen(false, "timer") end
	end)
end

local function startScanLoop()
	scanToken += 1
	local tk = scanToken
	task.spawn(function()
		task.wait(0.6)
		while P.running and scanToken == tk do
			local open, win = windowOpen()
			if not open then break end
			local found, rem, n = readWindow(win)
			if n > 0 then applySnapshot(found, rem) end
			task.wait(1)
		end
		if P.running and scanToken == tk then onWindowHidden() end
	end)
end

function P.scanNow()
	if not P.running then return false, "ระบบติดตามร้านลูกสูบยังปิดอยู่" end
	local open, win = windowOpen()
	if not open then return false, "หน้าร้านของเกมยังไม่เปิด (ไปที่ร้านแล้วเปิดหน้าซื้อก่อน)" end
	local found, rem, n = readWindow(win)
	if n == 0 then return false, "อ่านรายการสินค้าในหน้าร้านไม่ได้" end
	applySnapshot(found, rem)
	return true
end

----------------------------------------------------------------- สัญญาณอื่น
local function onNotice(name, ...)
	addSignal(name, describe(...))
	local txt = {}
	for i = 1, select("#", ...) do
		local v = select(i, ...)
		if type(v) == "string" then txt[#txt + 1] = v end
	end
	local j = table.concat(txt, " ")
	local low = j:lower()
	if j:find("ลูกสูบ", 1, true) or low:find("piston", 1, true) then
		local hasOpen = j:find("เปิด", 1, true) or low:find("open", 1, true)
		local hasClose = j:find("ปิด", 1, true) or low:find("closed", 1, true)
		if hasOpen then setOpen(true, "notice")
		elseif hasClose then setOpen(false, "notice") end
	end
end

local function hookRemotes()
	local m = maid
	task.spawn(function()
		local gr = RS:WaitForChild("GameRemotes", 10)
		if not gr or maid ~= m then return end
		local po = gr:FindFirstChild("PistonOpen")
		if po and po:IsA("RemoteEvent") then
			m:Give(po.OnClientEvent:Connect(function(...)
				addSignal("PistonOpen", describe(...))
				setOpen(true, "event")
				task.delay(1.2, function() if P.running and windowOpen() then startScanLoop() end end)
			end))
		end
		for _, n in ipairs({ "Notify", "Notice", "Announce" }) do
			local r = gr:FindFirstChild(n)
			if r and r:IsA("RemoteEvent") then
				m:Give(r.OnClientEvent:Connect(function(...) onNotice(n, ...) end))
			end
		end
	end)
end

local function hookSpots()
	local m = maid
	task.spawn(function()
		local map = workspace:WaitForChild("Map", 10)
		if not map or maid ~= m then return end
		local f = map:WaitForChild("PistonShopSpots", 10)
		if not f or maid ~= m then return end
		local function update()
			st.spotPos = nil
			for _, c in ipairs(f:GetChildren()) do
				if c:IsA("BasePart") then st.spotPos = c.Position break end
			end
			Bus.fire("PistonUpdate")
		end
		update()
		m:Give(f.ChildAdded:Connect(function(c)
			addSignal("Spot+", c.Name)
			update()
			if Config.get("pistonSigSpot") then setOpen(true, "spot") end
		end))
		m:Give(f.ChildRemoved:Connect(function(c)
			addSignal("Spot-", c.Name)
			task.defer(update)
			if Config.get("pistonSigSpot") and st.open == true and st.source == "spot" and #f:GetChildren() == 0 then setOpen(false, "spot") end
		end))
	end)
end

local function watchWindow()
	local m = maid
	task.spawn(function()
		local pg = LP:WaitForChild("PlayerGui", 10)
		if not pg or maid ~= m then return end
		local g = pg:WaitForChild("PistonShop", 15)
		if not g or maid ~= m then return end
		local win = g:WaitForChild("PistonShopWindow", 15)
		if not win or maid ~= m then return end
		local function chk() if P.running and windowOpen() then startScanLoop() end end
		m:Give(win:GetPropertyChangedSignal("Visible"):Connect(chk))
		m:Give(g:GetPropertyChangedSignal("Enabled"):Connect(chk))
		chk()
	end)
end

----------------------------------------------------------------- start / stop (ลงทะเบียนใน Registry)
function P.start()
	if P.running then return end
	gp = nil
	maid = Maid.new()
	P.running = true
	scanToken += 1
	if next(st.items) == nil then resetItems() end
	hookRemotes()
	hookSpots()
	watchWindow()
	Log.write("piston", "ok", "เริ่มติดตามร้านลูกสูบ")
end

function P.stop()
	P.running = false
	scanToken += 1
	if maid then maid:Clean() maid = nil end
	pending, flushScheduled = {}, false
	Bus.fire("PistonUpdate")
end

function P.clearHistory()
	P.history = {}
	saveHistory()
	Bus.fire("PistonUpdate")
end

P.windowOpen = windowOpen
P.gamePrices = gamePrices
if next(st.items) == nil then resetItems() end

return P

end
__mods["UI/Components"] = function()
-- คอมโพเนนต์ UI (ปุ่มสูง >= 40px เหมาะกับการแตะบนมือถือ)
