-- o = { title, desc, default, onChange(bool) } คืน { set, get }
function C.toggle(parent, o)
	local row = new("TextButton", {
		BackgroundColor3 = Theme.card, BackgroundTransparency = 0.1, BorderSizePixel = 0, AutoButtonColor = false,
		Text = "", Size = UDim2.new(1, 0, 0, o.desc and 56 or 44), Parent = parent,
