	Util.stroke(row, Theme.emerald, 1, 0.75)
	text(row, o.title, 14, Theme.white, Theme.fontBold, {
		Size = UDim2.new(1, -70, 0, 20), Position = UDim2.fromOffset(12, o.desc and 8 or 12), TextTruncate = Enum.TextTruncate.AtEnd,
	})
	if o.desc then
		text(row, o.desc, 11, Theme.dim, Theme.fontMed, {
			Size = UDim2.new(1, -70, 0, 24), Position = UDim2.fromOffset(12, 28), TextWrapped = true, TextYAlignment = Enum.TextYAlignment.Top,
		})
	end
	local sw = new("Frame", {
		AnchorPoint = Vector2.new(1, 0.5), Position = UDim2.new(1, -12, 0.5, 0), Size = UDim2.fromOffset(46, 24),
		BackgroundColor3 = Theme.off, BorderSizePixel = 0, Parent = row,
	})
	Util.corner(sw, 12)
	local knob = new("Frame", {
		Size = UDim2.fromOffset(18, 18), Position = UDim2.fromOffset(3, 3), BackgroundColor3 = Theme.white, BorderSizePixel = 0, Parent = sw,
	})
	Util.corner(knob, 9)
	local state = false
	local obj = {}
	function obj.set(v, silent)
		state = v and true or false
		Util.tween(sw, { BackgroundColor3 = state and Theme.emerald or Theme.off }, 0.15)
		Util.tween(knob, { Position = state and UDim2.fromOffset(25, 3) or UDim2.fromOffset(3, 3) }, 0.15)
		if not silent and o.onChange then o.onChange(state) end
	end
	function obj.get() return state end
	row.Activated:Connect(function() obj.set(not state) end)
	obj.set(o.default, true)
	return obj
end

-- o = { title, min, max, step, value, format(v), onChange(v) }  ใช้ maid ที่ส่งมาเก็บ connection
function C.slider(parent, o, maid)
	local row = new("Frame", {
		BackgroundColor3 = Theme.card, BackgroundTransparency = 0.1, BorderSizePixel = 0, Size = UDim2.new(1, 0, 0, 62), Parent = parent,
	})
	Util.corner(row, 10)
	Util.stroke(row, Theme.emerald, 1, 0.75)
	text(row, o.title, 14, Theme.white, Theme.fontBold, { Size = UDim2.new(0.6, 0, 0, 20), Position = UDim2.fromOffset(12, 6) })
	local val = text(row, "", 13, Theme.neon, Theme.fontBold, {
		Size = UDim2.new(0.4, -12, 0, 20), Position = UDim2.new(0.6, 0, 0, 6), TextXAlignment = Enum.TextXAlignment.Right,
	})
	local hit = new("TextButton", {
		BackgroundTransparency = 1, Text = "", Size = UDim2.new(1, -24, 0, 30), Position = UDim2.fromOffset(12, 28), Parent = row,
	})
	local bar = new("Frame", {
		AnchorPoint = Vector2.new(0, 0.5), Position = UDim2.fromScale(0, 0.5), Size = UDim2.new(1, 0, 0, 8),
		BackgroundColor3 = Theme.off, BorderSizePixel = 0, Parent = hit,
	})
	Util.corner(bar, 4)
	local fill = new("Frame", { Size = UDim2.fromScale(0, 1), BackgroundColor3 = Theme.emerald, BorderSizePixel = 0, Parent = bar })
	Util.corner(fill, 4)
	local knob = new("Frame", {
		AnchorPoint = Vector2.new(0.5, 0.5), Position = UDim2.fromScale(1, 0.5), Size = UDim2.fromOffset(20, 20),
		BackgroundColor3 = Theme.white, BorderSizePixel = 0, Parent = fill,
	})
	Util.corner(knob, 10)
	Util.stroke(knob, Theme.neon, 1.5, 0)

	local function show(v)
		local a = (v - o.min) / (o.max - o.min)
		fill.Size = UDim2.fromScale(math.clamp(a, 0, 1), 1)
		val.Text = o.format and o.format(v) or tostring(v)
	end
	local function fromX(x)
		local w = bar.AbsoluteSize.X
		if w <= 0 then return end
		local a = math.clamp((x - bar.AbsolutePosition.X) / w, 0, 1)
		local v = o.min + a * (o.max - o.min)
		v = math.floor(v / o.step + 0.5) * o.step
		v = math.clamp(v, o.min, o.max)
		show(v)
		if o.onChange then o.onChange(v) end
	end
	Util.drag(hit, maid, function(p) fromX(p.X) end, function(_, _, p) fromX(p.X) end)
	show(o.value)
	return { set = show }
end

-- ช่องกรอกข้อความ (วางลิงก์ได้)
function C.input(parent, placeholder)
	local tb = new("TextBox", {
		BackgroundColor3 = Theme.card, BackgroundTransparency = 0.05, BorderSizePixel = 0, Text = "",
		PlaceholderText = placeholder or "", PlaceholderColor3 = Theme.dim, TextColor3 = Theme.white, TextSize = Theme.sz(13),
		Font = Theme.fontMed, TextXAlignment = Enum.TextXAlignment.Left, ClearTextOnFocus = false,
		TextTruncate = Enum.TextTruncate.AtEnd, Size = UDim2.new(1, 0, 0, 42), Parent = parent,
	})
	Util.corner(tb, 10)
	local st = Util.stroke(tb, Theme.emerald, 1.2, 0.5)
	Util.padding(tb, 10, 0, 10, 0)
	tb.Focused:Connect(function() Util.tween(st, { Transparency = 0, Color = Theme.neon }, 0.12) end)
	tb.FocusLost:Connect(function() Util.tween(st, { Transparency = 0.5, Color = Theme.emerald }, 0.12) end)
	return tb
end

-- แถวสีให้แตะเลือก list = { "39FF8C", ... } onPick(hex)
function C.swatches(parent, list, onPick)
	local f = new("Frame", { BackgroundTransparency = 1, Size = UDim2.new(1, 0, 0, 0), AutomaticSize = Enum.AutomaticSize.Y, Parent = parent })
	new("UIGridLayout", { CellSize = UDim2.fromOffset(44, 44), CellPadding = UDim2.fromOffset(8, 8), SortOrder = Enum.SortOrder.LayoutOrder, Parent = f })
	for i, hex in ipairs(list) do
		local b = new("TextButton", {
			LayoutOrder = i, Text = "", AutoButtonColor = false, BackgroundColor3 = Theme.parseHex(hex, Theme.card),
			BorderSizePixel = 0, Parent = f,
		})
		Util.corner(b, 10)
		Util.stroke(b, Theme.white, 1.5, 0.6)
		b.Activated:Connect(function() onPick(hex) end)
	end
	return f
end

return C

end
__mods["UI/Hub"] = function()
-- หน้าต่างหลักของ HUB: ลาก / ย่อ / ปรับขนาด / UIScale / เมนู / ปุ่มหยุดฉุกเฉิน
local Players = game:GetService("Players")
local UIS = game:GetService("UserInputService")
local Maid = require("Core/Maid")
local Util = require("Core/Util")
local Theme = require("Core/Theme")
local Bus = require("Core/Bus")
local Config = require("Core/Config")
local Registry = require("Core/Registry")
local Notify = require("Core/Notify")
local Components = require("UI/Components")
local Toasts = require("UI/Toasts")
local StatusBar = require("UI/StatusBar")
local Assets = require("Core/Assets")
local new = Util.new

local TITLE_H, STATUS_H, SIDE_W = 46, 28, 146
local HEAD_H = TITLE_H + STATUS_H
local MIN_W, MIN_H, MAX_W, MAX_H = 520, 300, 1000, 700

local Hub = { pages = {}, version = "V6 · UI Phase 2" }
local S = {} -- state

local function parentGui(gui)
	local ok = pcall(function()
		if type(gethui) == "function" then gui.Parent = gethui() else gui.Parent = game:GetService("CoreGui") end
	end)
	if not ok or not gui.Parent then gui.Parent = Players.LocalPlayer:WaitForChild("PlayerGui") end
end

local function updateScale()
	local vp = S.gui.AbsoluteSize
	local fit = math.min(vp.X / (S.w + 24), vp.Y / (S.h + 24), 1.25)
	S.scale.Scale = math.clamp(fit, 0.45, 1.25) * Config.get("uiScale")
end

local function clampPos()
	local s, vp = S.scale.Scale, S.gui.AbsoluteSize
	local w = S.w * s
	local p = S.win.Position
	S.win.Position = UDim2.fromOffset(
		math.clamp(p.X.Offset, -(w - 90), vp.X - 90),
		math.clamp(p.Y.Offset, 0, vp.Y - 50)
	)
end

local function clearContent()
	for _, c in ipairs(S.content:GetChildren()) do
		if not c:IsA("UIListLayout") and not c:IsA("UIPadding") then c:Destroy() end
	end
end

function Hub.open(id)
	local def
	for _, p in ipairs(Hub.pages) do if p.id == id then def = p end end
	if not def then return end
	if S.pageMaid then S.pageMaid:Clean() end
	clearContent()
	S.pageMaid = Maid.new()
	S.current = id
	S.content.CanvasPosition = Vector2.zero
	for pid, b in pairs(S.navButtons) do
		local on = pid == id
		Util.tween(b, { BackgroundColor3 = on and Theme.cardHi or Theme.card, BackgroundTransparency = on and 0 or 0.35 }, 0.15)
		b.Bar.Visible = on
	end
	Components.section(S.content, def.titleTh .. "  ·  " .. def.titleEn)
	local ok, err = pcall(def.build, { parent = S.content, maid = S.pageMaid, C = Components, hub = Hub })
	if not ok then
		Components.label(S.content, "<font color='#F85A5A'>หน้านี้เกิดข้อผิดพลาด:</font> " .. tostring(err))
		warn("[BALLKUN] page " .. id .. ": " .. tostring(err))
	end
end

local function buildNav()
	for _, b in pairs(S.navButtons) do b:Destroy() end
	S.navButtons = {}
	table.sort(Hub.pages, function(a, b) return a.order < b.order end)
	for i, p in ipairs(Hub.pages) do
		local b = new("TextButton", {
			AutoButtonColor = false, Text = "", LayoutOrder = i, Size = UDim2.new(1, 0, 0, 46),
			BackgroundColor3 = Theme.card, BackgroundTransparency = 0.35, BorderSizePixel = 0, Parent = S.side,
		})
		Util.corner(b, 10)
		local bar = new("Frame", {
			Name = "Bar", Size = UDim2.new(0, 3, 0.6, 0), Position = UDim2.new(0, 3, 0.2, 0),
			BackgroundColor3 = Theme.neon, BorderSizePixel = 0, Visible = false, Parent = b,
		})
		Util.corner(bar, 2)
		Components.text(b, p.titleTh, 13, Theme.white, Theme.fontBold, { Size = UDim2.new(1, -16, 0, 20), Position = UDim2.fromOffset(12, 5), TextTruncate = Enum.TextTruncate.AtEnd })
		Components.text(b, p.titleEn, 10, Theme.dim, Theme.fontMed, { Size = UDim2.new(1, -16, 0, 14), Position = UDim2.fromOffset(12, 25), TextTruncate = Enum.TextTruncate.AtEnd })
		b.Activated:Connect(function() Hub.open(p.id) end)
		S.navButtons[p.id] = b
	end
	if S.current and S.navButtons[S.current] then
		S.navButtons[S.current].BackgroundColor3 = Theme.cardHi
		S.navButtons[S.current].BackgroundTransparency = 0
		S.navButtons[S.current].Bar.Visible = true
	end
end

-- def = { id, titleTh, titleEn, order, build = function(ctx) }
function Hub.addPage(def)
	for i, p in ipairs(Hub.pages) do if p.id == def.id then table.remove(Hub.pages, i) break end end
	table.insert(Hub.pages, def)
	if S.side then buildNav() end
end

function Hub.setVisible(v)
	S.token = (S.token or 0) + 1
	local tk = S.token
	S.visible = v
	local target = S.scale.Scale
	if v then
		S.bubble.Visible = false
		S.win.Visible = true
		S.scale.Scale = target * 0.88
		Util.tween(S.scale, { Scale = target }, 0.18, Enum.EasingStyle.Back)
	else
		Util.tween(S.scale, { Scale = target * 0.88 }, 0.12)
		task.delay(0.13, function()
			if S.token ~= tk then return end
			S.win.Visible = false
			S.bubble.Visible = true
			updateScale()
		end)
	end
end

local function titleButton(parent, txt, w, style, cb)
	return Components.button(parent, txt, cb, { style = style, size = 13, fixed = UDim2.fromOffset(w, 36) })
end

function Hub.init()
	Hub.destroy()
	local lp = Players.LocalPlayer
	S.maid = Maid.new()
	S.w, S.h = Config.get("windowW"), Config.get("windowH")
	S.navButtons, S.visible = {}, true

	S.gui = new("ScreenGui", {
		Name = "BK_" .. tostring(math.random(100000, 999999)), ResetOnSpawn = false, IgnoreGuiInset = true,
		DisplayOrder = 999, ZIndexBehavior = Enum.ZIndexBehavior.Sibling,
	})
	parentGui(S.gui)

	-- หน้าต่างหลัก
	S.win = new("Frame", {
		Name = "Window", Active = true, Size = UDim2.fromOffset(S.w, S.h), BackgroundColor3 = Theme.panel,
		BackgroundTransparency = Config.get("glass"), BorderSizePixel = 0, Parent = S.gui,
	})
	Util.corner(S.win, 14)
	Util.stroke(S.win, Theme.neon, 1.5, 0.45)
	Util.gradient(S.win, Color3.fromRGB(18, 40, 30), Color3.fromRGB(4, 9, 7), 120)
	S.scale = new("UIScale", { Parent = S.win })
	-- ภาพพื้นหลัง (อยู่ใต้ทุกอย่าง)
	S.bg = new("ImageLabel", {
		Name = "Bg", ZIndex = 0, BackgroundTransparency = 1, Size = UDim2.fromScale(1, 1), ScaleType = Enum.ScaleType.Crop,
		ImageTransparency = 1 - math.clamp(Config.get("bgVisible"), 0, 1), Visible = false, Parent = S.win,
	})
	Util.corner(S.bg, 14)
	if Config.get("bgEnabled") then
		local custom = tostring(Config.get("bgAsset") or ""):match("%d+")
		local url = custom and ("rbxassetid://" .. custom) or Assets.bgUrl()
		if url then S.bg.Image = url S.bg.Visible = true end
	end
	S.maid:Give(Bus.on("Config:bgVisible", function(v) if S.bg then S.bg.ImageTransparency = 1 - math.clamp(v, 0, 1) end end))
	updateScale()
	local vp = S.gui.AbsoluteSize
	S.win.Position = UDim2.fromOffset(math.max(0, (vp.X - S.w * S.scale.Scale) / 2), math.max(0, (vp.Y - S.h * S.scale.Scale) / 2))
	S.maid:Give(S.gui:GetPropertyChangedSignal("AbsoluteSize"):Connect(function() updateScale() clampPos() end))
	S.maid:Give(Bus.on("Config:uiScale", updateScale))
	S.maid:Give(Bus.on("Config:glass", function(v) S.win.BackgroundTransparency = v end))

	-- แถบหัว
	local tb = new("Frame", { Name = "TitleBar", Size = UDim2.new(1, 0, 0, TITLE_H), BackgroundTransparency = 1, Parent = S.win })
	new("Frame", { Size = UDim2.new(1, -16, 0, 1), Position = UDim2.new(0, 8, 1, 0), BackgroundColor3 = Theme.emerald, BackgroundTransparency = 0.6, BorderSizePixel = 0, Parent = tb })
	Components.text(tb, "BALL KUN", 19, Theme.neon, Theme.fontBlack, { Size = UDim2.fromOffset(120, 24), Position = UDim2.fromOffset(14, 5) })
	Components.text(tb, "MAHANAKHON AI AUTO HUB V6", 10, Theme.dim, Theme.fontBold, { Size = UDim2.fromOffset(200, 14), Position = UDim2.fromOffset(14, 28) })

	local right = new("Frame", {
		AnchorPoint = Vector2.new(1, 0.5), Position = UDim2.new(1, -8, 0.5, 0), Size = UDim2.new(0, 0, 0, 36),
		AutomaticSize = Enum.AutomaticSize.X, BackgroundTransparency = 1, Parent = tb,
	})
	new("UIListLayout", {
		FillDirection = Enum.FillDirection.Horizontal, Padding = UDim.new(0, 6), SortOrder = Enum.SortOrder.LayoutOrder,
		HorizontalAlignment = Enum.HorizontalAlignment.Right, VerticalAlignment = Enum.VerticalAlignment.Center, Parent = right,
	})
	local stop = titleButton(right, "■ STOP ALL", 96, "danger", function()
		Registry.stopAll("ผู้ใช้กดปุ่มหยุดระบบทั้งหมด")
	end)
	stop.LayoutOrder = 2
	titleButton(right, "—", 38, "ghost", function() Hub.setVisible(false) end).LayoutOrder = 3
	local closeBtn
	local armed = false
	closeBtn = titleButton(right, "✕", 38, "ghost", function()
		if not armed then
			armed = true
			closeBtn.Text = "?"
			Notify.push({ title = "แตะ ✕ อีกครั้งเพื่อปิด HUB", text = "ระบบทั้งหมดจะหยุดและ UI จะถูกลบ", level = "warn", key = "closeconfirm", cooldown = 0 })
			task.delay(2.5, function() armed = false if closeBtn.Parent then closeBtn.Text = "✕" end end)
			return
		end
		Registry.stopAll("ปิด HUB")
		Hub.destroy()
	end)
	closeBtn.LayoutOrder = 4

	-- ลากหน้าต่างจากแถบหัว
	local startPos
	Util.drag(tb, S.maid, function() startPos = S.win.Position end, function(dx, dy)
		S.win.Position = UDim2.fromOffset(startPos.X.Offset + dx, startPos.Y.Offset + dy)
	end, clampPos)

	-- แถบสถานะ (เลื่อนซ้าย-ขวาได้บนมือถือ)
	local status = new("ScrollingFrame", {
		Name = "Status", Position = UDim2.fromOffset(8, TITLE_H + 3), Size = UDim2.new(1, -16, 0, 24), BackgroundTransparency = 1,
		BorderSizePixel = 0, ScrollBarThickness = 0, ScrollingDirection = Enum.ScrollingDirection.X,
		CanvasSize = UDim2.new(), AutomaticCanvasSize = Enum.AutomaticSize.X, Parent = S.win,
	})
	StatusBar.build(status, S.maid)

	-- เมนูด้านข้าง + เนื้อหา
	S.side = new("ScrollingFrame", {
		Name = "Side", Position = UDim2.fromOffset(8, HEAD_H + 4), Size = UDim2.new(0, SIDE_W, 1, -(HEAD_H + 12)),
		BackgroundTransparency = 1, BorderSizePixel = 0, ScrollBarThickness = 3, ScrollBarImageColor3 = Theme.emerald,
		CanvasSize = UDim2.new(), AutomaticCanvasSize = Enum.AutomaticSize.Y, Parent = S.win,
	})
	new("UIListLayout", { Padding = UDim.new(0, 6), SortOrder = Enum.SortOrder.LayoutOrder, Parent = S.side })
	S.content = new("ScrollingFrame", {
		Name = "Content", Position = UDim2.fromOffset(SIDE_W + 16, HEAD_H + 4), Size = UDim2.new(1, -(SIDE_W + 24), 1, -(HEAD_H + 12)),
		BackgroundTransparency = 1, BorderSizePixel = 0, ScrollBarThickness = 4, ScrollBarImageColor3 = Theme.emerald,
		CanvasSize = UDim2.new(), AutomaticCanvasSize = Enum.AutomaticSize.Y, Parent = S.win,
	})
	new("UIListLayout", { Padding = UDim.new(0, 8), SortOrder = Enum.SortOrder.LayoutOrder, Parent = S.content })
	Util.padding(S.content, 2, 2, 8, 12)

	-- ปรับขนาด
	local grip = new("TextLabel", {
		Text = "◢", Font = Theme.fontBold, TextSize = 18, TextColor3 = Theme.neon, BackgroundTransparency = 1,
		AnchorPoint = Vector2.new(1, 1), Position = UDim2.new(1, -2, 1, -2), Size = UDim2.fromOffset(30, 30), Active = true, ZIndex = 5, Parent = S.win,
	})
	local w0, h0
	Util.drag(grip, S.maid, function() w0, h0 = S.w, S.h end, function(dx, dy)
		local s = S.scale.Scale
		S.w = math.clamp(w0 + dx / s, MIN_W, MAX_W)
		S.h = math.clamp(h0 + dy / s, MIN_H, MAX_H)
		S.win.Size = UDim2.fromOffset(S.w, S.h)
	end, function()
		Config.set("windowW", math.floor(S.w))
		Config.set("windowH", math.floor(S.h))
		updateScale()
		clampPos()
	end)

	-- ปุ่มลอย (ตอนย่อ): แตะเพื่อเปิด ลากเพื่อย้าย
	S.bubble = new("TextButton", {
		Name = "Bubble", Visible = false, AutoButtonColor = false, Text = "BK", Font = Theme.fontBlack, TextSize = 18,
		TextColor3 = Theme.neon, Size = UDim2.fromOffset(52, 52), Position = UDim2.fromOffset(14, 130),
		BackgroundColor3 = Theme.panel, BackgroundTransparency = 0.05, BorderSizePixel = 0, Parent = S.gui,
	})
	Util.corner(S.bubble, 26)
	Util.stroke(S.bubble, Theme.neon, 2, 0.2)
	local bp, moved = nil, 0
	Util.drag(S.bubble, S.maid, function() bp, moved = S.bubble.Position, 0 end, function(dx, dy)
		moved = math.max(moved, math.abs(dx) + math.abs(dy))
		local v = S.gui.AbsoluteSize
		S.bubble.Position = UDim2.fromOffset(math.clamp(bp.X.Offset + dx, 0, v.X - 52), math.clamp(bp.Y.Offset + dy, 0, v.Y - 52))
	end, function()
		if moved < 8 then Hub.setVisible(true) end
	end)

	-- ปุ่มลัดบนคอม: RightShift
	S.maid:Give(UIS.InputBegan:Connect(function(i, gp)
		if not gp and i.KeyCode == Enum.KeyCode.RightShift then Hub.setVisible(not S.visible) end
	end))

	Toasts.init(S.gui, S.maid)
	buildNav()
	Hub.setVisible(true)
end

function Hub.destroy()
	if S.pageMaid then S.pageMaid:Clean() end
	if S.maid then S.maid:Clean() end
	if S.gui then S.gui:Destroy() end
	S = {}
end

-- สร้าง UI ใหม่ทั้งชุด (ใช้ตอนเปลี่ยนธีม/ฟอนต์/ภาพพื้นหลัง) คงตำแหน่ง หน้าปัจจุบัน และสถานะย่อไว้
function Hub.rebuild()
	if not S.gui then return end
	local cur, pos, bpos, vis = S.current, S.win.Position, S.bubble.Position, S.visible
	Hub.init()
	S.win.Position, S.bubble.Position = pos, bpos
	clampPos()
	if cur then Hub.open(cur) end
	if not vis then Hub.setVisible(false) end
end

function Hub.isAlive() return S.gui ~= nil and S.gui.Parent ~= nil end

return Hub

end
__mods["UI/StatusBar"] = function()
-- แถบสถานะ (event-driven): ร้านลูกสูบ · Discord · ลิงก์เซิร์ฟ · ระบบที่เปิด · ผู้เล่น
local Players = game:GetService("Players")
local Util = require("Core/Util")
local Theme = require("Core/Theme")
local Bus = require("Core/Bus")
local Registry = require("Core/Registry")
local Discord = require("Core/Discord")
local Piston = require("Systems/Piston")
local new = Util.new

local SB = {}

local function hex(c) return "#" .. Theme.toHex(c) end
local function paint(txt, c) return string.format("<font color='%s'>%s</font>", hex(c), txt) end

function SB.build(parent, maid)
	new("UIListLayout", {
		FillDirection = Enum.FillDirection.Horizontal, Padding = UDim.new(0, 6), SortOrder = Enum.SortOrder.LayoutOrder,
		VerticalAlignment = Enum.VerticalAlignment.Center, Parent = parent,
	})
	local chips = {}
	local function mk(key, order)
		local l = new("TextLabel", {
			LayoutOrder = order, AutomaticSize = Enum.AutomaticSize.X, Size = UDim2.fromOffset(0, 22),
			BackgroundColor3 = Theme.card, BackgroundTransparency = 0.15, BorderSizePixel = 0, RichText = true,
			Font = Theme.fontBold, TextSize = Theme.sz(11), TextColor3 = Theme.white, Text = "", Parent = parent,
		})
		Util.corner(l, 11)
		Util.stroke(l, Theme.emerald, 1, 0.7)
		Util.padding(l, 8, 0)
		chips[key] = l
	end
	mk("shop", 1) mk("dc", 2) mk("link", 3) mk("sys", 4) mk("ply", 5)

	local st = Piston.st
	local function refresh()
		if not chips.shop or not chips.shop.Parent then return end
		local shop
		if not Registry.isEnabled("piston") then shop = paint("ปิดระบบ", Theme.dim)
		elseif st.open == true then shop = paint("OPEN", Theme.ok)
		elseif st.open == false then shop = paint("CLOSED", Theme.crit)
		else shop = paint("UNKNOWN", Theme.warn) end
		chips.shop.Text = "🏪 ร้านลูกสูบ " .. shop
		chips.dc.Text = "💬 Discord " .. (Discord.hasUrl() and paint("พร้อม", Theme.ok) or paint("ยังไม่ตั้ง", Theme.warn))
		local link, kind = Discord.serverLink()
		local k = kind == "private" and "PRIVATE" or "PUBLIC"
		chips.link.Text = "🔗 ลิงก์ " .. (link and paint(k, Theme.ok) or paint("ไม่มี (" .. k .. ")", Theme.warn))
		chips.sys.Text = "⚙ ระบบ ON " .. Registry.countEnabled() .. "/" .. #Registry.list()
		chips.ply.Text = "👥 " .. #Players:GetPlayers() .. "/" .. Players.MaxPlayers
	end
	refresh()
	for _, ev in ipairs({ "PistonUpdate", "SystemChanged", "DiscordChanged", "LinkChanged" }) do
		maid:Give(Bus.on(ev, refresh))
	end
	maid:Give(Players.PlayerAdded:Connect(refresh))
	maid:Give(Players.PlayerRemoving:Connect(function() task.defer(refresh) end))
end

return SB

end
__mods["UI/Toasts"] = function()
-- ป๊อปอัปแจ้งเตือน (event-driven จาก Bus "Notify")
local Util = require("Core/Util")
local Theme = require("Core/Theme")
local Bus = require("Core/Bus")
local Config = require("Core/Config")
local new = Util.new

local Toasts = {}
local DUR = { info = 3.5, ok = 3.5, warn = 5.5, crit = 9 }

function Toasts.init(gui, maid)
	local holder = new("Frame", {
		Name = "Toasts", AnchorPoint = Vector2.new(0.5, 0), Position = UDim2.new(0.5, 0, 0, 58),
		Size = UDim2.fromOffset(300, 10), BackgroundTransparency = 1, Parent = gui,
	})
	new("UIListLayout", {
		Padding = UDim.new(0, 6), SortOrder = Enum.SortOrder.LayoutOrder,
		HorizontalAlignment = Enum.HorizontalAlignment.Center, Parent = holder,
	})
	local sc = new("UIScale", { Parent = holder })
	local function fit() sc.Scale = math.clamp(gui.AbsoluteSize.X / 340, 0.6, 1) end
	fit()
	maid:Give(gui:GetPropertyChangedSignal("AbsoluteSize"):Connect(fit))

	local order = 0
	maid:Give(Bus.on("Notify", function(n)
		if n.level ~= "crit" and n.priority < Config.get("minToastPriority") then return end
		order += 1
		local color = Theme.levelColor(n.level)
		local t = new("TextButton", {
			AutoButtonColor = false, Text = "", LayoutOrder = order, Size = UDim2.new(1, 0, 0, 0),
			AutomaticSize = Enum.AutomaticSize.Y, BackgroundColor3 = Theme.panel, BackgroundTransparency = 1,
			BorderSizePixel = 0, Parent = holder,
		})
		Util.corner(t, 10)
		local st = Util.stroke(t, color, 1.4, 1)
		Util.padding(t, 14, 8, 10, 8)
		new("Frame", { Size = UDim2.new(0, 4, 1, 0), Position = UDim2.fromOffset(-14, 0), BackgroundColor3 = color, BorderSizePixel = 0, Parent = t })
		local box = new("Frame", { BackgroundTransparency = 1, Size = UDim2.new(1, 0, 0, 0), AutomaticSize = Enum.AutomaticSize.Y, Parent = t })
		new("UIListLayout", { Padding = UDim.new(0, 2), Parent = box })
		new("TextLabel", {
			BackgroundTransparency = 1, Text = n.title or "", Font = Theme.fontBold, TextSize = Theme.sz(14), TextColor3 = color,
			TextXAlignment = Enum.TextXAlignment.Left, Size = UDim2.new(1, 0, 0, 18), LayoutOrder = 1, Parent = box,
		})
		if n.text and n.text ~= "" then
			new("TextLabel", {
				BackgroundTransparency = 1, Text = n.text, Font = Theme.fontMed, TextSize = Theme.sz(12), TextColor3 = Theme.white,
				TextWrapped = true, TextXAlignment = Enum.TextXAlignment.Left, TextYAlignment = Enum.TextYAlignment.Top,
				Size = UDim2.new(1, 0, 0, 0), AutomaticSize = Enum.AutomaticSize.Y, LayoutOrder = 2, Parent = box,
			})
		end
		Util.tween(t, { BackgroundTransparency = 0.08 }, 0.2)
		Util.tween(st, { Transparency = 0.2 }, 0.2)

		local dead = false
		local function close()
			if dead then return end
			dead = true
			Util.tween(t, { BackgroundTransparency = 1 }, 0.15)
			task.delay(0.16, function() t:Destroy() end)
		end
		t.Activated:Connect(close)
		task.delay((DUR[n.level] or 4) * (Config.get("toastTime") or 1), close)

		-- จำกัดจำนวนที่แสดง
		local alive = {}
		for _, c in ipairs(holder:GetChildren()) do if c:IsA("TextButton") then table.insert(alive, c) end end
		table.sort(alive, function(a, b) return a.LayoutOrder < b.LayoutOrder end)
		while #alive > (Config.get("toastMax") or 4) do table.remove(alive, 1):Destroy() end
	end))
end

return Toasts

end
__mods["Main"] = function()
local Config = require("Core/Config")
local Notify = require("Core/Notify")
local Log = require("Core/Log")
local Bus = require("Core/Bus")
local Hub = require("UI/Hub")
local Registry = require("Core/Registry")
local Piston = require("Systems/Piston")

local Main = {}

function Main.start()
	local genv = (type(getgenv) == "function" and getgenv()) or _G
	if genv.BALLKUN_V6 and genv.BALLKUN_V6.Destroy then pcall(genv.BALLKUN_V6.Destroy) end -- กันรันซ้ำ

	Config.load()
	require("Core/Theme").apply(Config.data)
	require("Core/Discord").load()
	Piston.load()
	Registry.register({ id = "piston", nameTh = "ร้านลูกสูบ", nameEn = "Piston Radar", start = Piston.start, stop = Piston.stop })
	Hub.init()
	Hub.addPage(require("Pages/Dashboard"))
	Hub.addPage(require("Pages/Systems"))
	Hub.addPage(require("Pages/Server"))
	Hub.addPage(require("Pages/Piston"))
	Hub.addPage(require("Pages/Discord"))
	Hub.addPage(require("Pages/Notifications"))
	Hub.addPage(require("Pages/Theme"))
	Hub.addPage(require("Pages/Settings"))
	Hub.open("dashboard")
	if Config.get("pistonAutoStart") then Registry.setEnabled("piston", true) end

	genv.BALLKUN_V6 = {
		Version = Hub.version,
		Destroy = function()
			pcall(Piston.stop)
			Hub.destroy()
			Bus.reset()
			genv.BALLKUN_V6 = nil
		end,
	}

	Log.write("core", "ok", "HUB เริ่มทำงาน")
	if game.PlaceId ~= 104549080643413 then
		Notify.push({ title = "PlaceId ไม่ตรง", text = "สคริปต์นี้ทำมาสำหรับ MAHANAKHON RACING (104549080643413)", level = "warn" })
	else
		Notify.push({ title = "BALL KUN HUB V6", text = "พร้อมใช้งาน (UI + ร้านลูกสูบ + ลิงก์เซิร์ฟ)", level = "ok" })
	end
end

return Main

end
require("Main").start()
